import React from 'react'
import { Modal, Table } from 'antd'
import { DndContext, closestCenter, useSensor, useSensors, PointerSensor, KeyboardSensor } from '@dnd-kit/core'
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
  useSortable,
} from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'

interface DraggableTableModalProps<T> {
  open: boolean
  onCancel: () => void
  title: string
  columns: any[]
  dataSource: T[]
  rowKey: string
  onChangeOrder: (newData: T[]) => void
  addRowRender?: React.ReactNode
  footer?: React.ReactNode
  width?: number | string
}

function Row(props: any) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: props['data-row-key'],
  })
  const style: React.CSSProperties = {
    ...props.style,
    transform: CSS.Translate.toString(transform),
    transition,
    cursor: 'move',
    ...(isDragging ? { position: 'relative', zIndex: 9999 } : {}),
  }
  return <tr {...props} ref={setNodeRef} style={style} {...attributes} {...listeners} />
}

function DraggableTableModal<T extends { [key: string]: any }>({
  open,
  onCancel,
  title,
  columns,
  dataSource,
  rowKey,
  onChangeOrder,
  addRowRender,
  footer,
  width = 800,
}: DraggableTableModalProps<T>) {
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 1 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  )

  const handleDragEnd = (event: any) => {
    const { active, over } = event
    if (active.id !== over?.id) {
      const oldIndex = dataSource.findIndex(item => item[rowKey] === active.id)
      const newIndex = dataSource.findIndex(item => item[rowKey] === over?.id)
      const newItems = arrayMove(dataSource, oldIndex, newIndex)
      onChangeOrder(newItems)
    }
  }

  return (
    <Modal open={open} onCancel={onCancel} title={title} width={width} footer={footer ?? null}>
      <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
        <SortableContext items={dataSource.map(item => item[rowKey])} strategy={verticalListSortingStrategy}>
          <Table
            columns={columns}
            dataSource={dataSource}
            pagination={false}
            size='small'
            components={{ body: { row: Row } }}
            rowKey={rowKey}
          />
        </SortableContext>
      </DndContext>
      {addRowRender}
    </Modal>
  )
}

export default DraggableTableModal

import React from 'react'
import { Table } from 'antd'
import { DndContext, closestCenter, useSensor, useSensors, PointerSensor, KeyboardSensor } from '@dnd-kit/core'
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
  useSortable,
} from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'

interface DraggableTableProps<T> {
  columns: any[]
  dataSource: T[]
  rowKey: string
  onChangeOrder: (newData: T[]) => void
  onRowClick?: (record: T, index: number) => void
  onRowDoubleClick?: (record: T, index: number) => void
}

function Row(props: any) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: props['data-row-key'],
  })
  const style: React.CSSProperties = {
    ...props.style,
    transform: CSS.Translate.toString(transform),
    transition,
    cursor: 'move',
    ...(isDragging ? { position: 'relative', zIndex: 9999 } : {}),
  }
  return <tr {...props} ref={setNodeRef} style={style} {...attributes} {...listeners} />
}

function DraggableTable<T extends { [key: string]: any }>({
  columns,
  dataSource,
  rowKey,
  onChangeOrder,
  onRowClick,
  onRowDoubleClick,
}: DraggableTableProps<T>) {
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 1 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  )

  const handleDragEnd = (event: any) => {
    const { active, over } = event
    if (active.id !== over?.id) {
      const oldIndex = dataSource.findIndex(item => item[rowKey] === active.id)
      const newIndex = dataSource.findIndex(item => item[rowKey] === over?.id)
      const newItems = arrayMove(dataSource, oldIndex, newIndex)
      onChangeOrder(newItems)
    }
  }

  return (
    <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <SortableContext items={dataSource.map(item => item[rowKey])} strategy={verticalListSortingStrategy}>
        <Table
          columns={columns}
          dataSource={dataSource}
          pagination={false}
          size='small'
          components={{ body: { row: Row } }}
          rowKey={rowKey}
          onRow={(record, index) => ({
            onClick: () => {
              if (onRowClick) {
                onRowClick(record, index || 0)
              }
            },
            onDoubleClick: () => {
              if (onRowDoubleClick) {
                onRowDoubleClick(record, index || 0)
              }
            },
          })}
        />
      </SortableContext>
    </DndContext>
  )
}

export default DraggableTable

import React, { useState } from 'react'
import { Button, Input, Modal, Select, Radio, Space, message } from 'antd'
import { UploadOutlined, CloseOutlined } from '@ant-design/icons'
import styles from './lawyerApprovalModal.module.scss'
import { useFileUpload } from '@/hooks/useFileUpload'
import { useUpdateLawyerRegister } from '@/hooks/queries/useMember'

interface LawyerApprovalModalProps {
  open: boolean
  onCancel: () => void
  onSubmit?: (data: any) => void
  lawyerId: number | null
  defaultValues?: {
    lawSchoolDiploma?: string
    lawyerLicense?: string
    passingDate?: string
    approvalStatus?: 'pending' | 'approved'
  }
}

const LawyerApprovalModal: React.FC<LawyerApprovalModalProps> = ({
  open,
  onCancel,
  onSubmit,
  defaultValues,
  lawyerId,
}) => {
  const [lawSchoolDiplomaFile, setLawSchoolDiplomaFile] = useState<File | null>(null)
  const [lawyerLicenseFile, setLawyerLicenseFile] = useState<File | null>(null)
  const [lawSchoolDiplomaUrl, setLawSchoolDiplomaUrl] = useState<string>('')
  const [lawyerLicenseUrl, setLawyerLicenseUrl] = useState<string>('')
  const [passingYear, setPassingYear] = useState('')
  const [passingMonth, setPassingMonth] = useState('')
  const [passingDay, setPassingDay] = useState('')
  const [approvalStatus, setApprovalStatus] = useState<'pending' | 'approved'>('pending')
  const [isSubmitting, setIsSubmitting] = useState(false)

  // 초기값 저장용 state
  const [initialValues, setInitialValues] = useState<{
    lawSchoolDiploma: string
    lawyerLicense: string
    passingYear: string
    passingMonth: string
    passingDay: string
    approvalStatus: 'pending' | 'approved'
  }>({
    lawSchoolDiploma: '',
    lawyerLicense: '',
    passingYear: '',
    passingMonth: '',
    passingDay: '',
    approvalStatus: 'pending',
  })

  const { uploadFile } = useFileUpload()
  const updateLawyerRegister = useUpdateLawyerRegister({
    onSuccess: () => {
      message.success('변호사 승인 정보가 업데이트되었습니다.')
      onCancel()
    },
    onError: error => {
      message.error('업데이트에 실패했습니다.')
      console.error(error)
    },
  })

  React.useEffect(() => {
    if (open) {
      setLawSchoolDiplomaFile(null)
      setLawyerLicenseFile(null)

      const diplomaUrl = defaultValues?.lawSchoolDiploma || ''
      const licenseUrl = defaultValues?.lawyerLicense || ''
      let year = ''
      let month = ''
      let day = ''

      // 날짜 파싱
      if (defaultValues?.passingDate) {
        const date = new Date(defaultValues.passingDate)
        year = date.getFullYear().toString()
        month = (date.getMonth() + 1).toString().padStart(2, '0')
        day = date.getDate().toString().padStart(2, '0')
      }

      const status = defaultValues?.approvalStatus || 'pending'

      // 현재 값 설정
      setLawSchoolDiplomaUrl(diplomaUrl)
      setLawyerLicenseUrl(licenseUrl)
      setPassingYear(year)
      setPassingMonth(month)
      setPassingDay(day)
      setApprovalStatus(status)

      // 초기값 저장
      setInitialValues({
        lawSchoolDiploma: diplomaUrl,
        lawyerLicense: licenseUrl,
        passingYear: year,
        passingMonth: month,
        passingDay: day,
        approvalStatus: status,
      })
    }
  }, [open, defaultValues])

  // 값이 변경되었는지 확인하는 함수
  const hasChanges = () => {
    // 새 파일이 선택되었으면 변경된 것
    if (lawSchoolDiplomaFile || lawyerLicenseFile) {
      return true
    }

    // 기존 값과 현재 값 비교
    return (
      lawSchoolDiplomaUrl !== initialValues.lawSchoolDiploma ||
      lawyerLicenseUrl !== initialValues.lawyerLicense ||
      passingYear !== initialValues.passingYear ||
      passingMonth !== initialValues.passingMonth ||
      passingDay !== initialValues.passingDay ||
      approvalStatus !== initialValues.approvalStatus
    )
  }

  const handleSubmit = async () => {
    if (!lawyerId) {
      message.error('변호사 ID가 없습니다.')
      return
    }

    try {
      setIsSubmitting(true)

      let finalLawSchoolDiplomaUrl = lawSchoolDiplomaUrl
      let finalLawyerLicenseUrl = lawyerLicenseUrl

      // 파일 업로드 처리
      if (lawSchoolDiplomaFile) {
        const result = await uploadFile(lawSchoolDiplomaFile, {
          folder: 'lawyer/lawyerLawSchoolDiplomaUrl',
        })
        finalLawSchoolDiplomaUrl = result.fileUrl
      }

      if (lawyerLicenseFile) {
        const result = await uploadFile(lawyerLicenseFile, {
          folder: 'lawyer/certificateUrl',
        })
        finalLawyerLicenseUrl = result.fileUrl
      }

      // 승인 완료를 선택한 경우, 필수 정보 확인
      if (approvalStatus === 'approved') {
        const hasAllRequiredFields =
          finalLawSchoolDiplomaUrl && finalLawyerLicenseUrl && passingYear && passingMonth && passingDay

        if (!hasAllRequiredFields) {
          message.error('승인 완료를 위해서는 로스쿨 졸업장, 변호사 자격증, 변호사 합격일자를 모두 입력해야 합니다.')
          setIsSubmitting(false)
          return
        }
      }

      // API 요청 데이터 구성
      const requestData = {
        ...(finalLawSchoolDiplomaUrl && { lawyerLawSchoolDiplomaUrl: finalLawSchoolDiplomaUrl }),
        ...(finalLawyerLicenseUrl && { lawyerCertificateUrl: finalLawyerLicenseUrl }),
        ...(approvalStatus === 'pending' && { lawyerApprovalStatus: 1 as const }), // 대기 -> 1
        ...(approvalStatus === 'approved' && { lawyerApprovalStatus: 2 as const }), // 승인완료 -> 2
        ...(passingYear && { barExamPassYear: parseInt(passingYear) }),
        ...(passingMonth && { barExamPassMonth: parseInt(passingMonth) }),
        ...(passingDay && { barExamPassDay: parseInt(passingDay) }),
      }

      // 변호사 정보 업데이트
      await updateLawyerRegister.mutateAsync({
        lawyerId,
        request: requestData,
      })

      if (onSubmit) {
        onSubmit(requestData)
      }

      handleCancel()
    } catch (error) {
      console.error('Submit error:', error)
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleCancel = () => {
    setLawSchoolDiplomaFile(null)
    setLawyerLicenseFile(null)
    setLawSchoolDiplomaUrl('')
    setLawyerLicenseUrl('')
    setPassingYear('')
    setPassingMonth('')
    setPassingDay('')
    setApprovalStatus('pending')
    setIsSubmitting(false)
    onCancel()
  }

  const handleLawSchoolDiplomaUpload = (info: any) => {
    const file = info.target.files?.[0]
    if (file) {
      setLawSchoolDiplomaFile(file)
      const reader = new FileReader()
      reader.onload = e => {
        setLawSchoolDiplomaUrl(e.target?.result as string)
      }
      reader.readAsDataURL(file)
    }
  }

  const handleLawyerLicenseUpload = (info: any) => {
    const file = info.target.files?.[0]
    if (file) {
      setLawyerLicenseFile(file)
      const reader = new FileReader()
      reader.onload = e => {
        setLawyerLicenseUrl(e.target?.result as string)
      }
      reader.readAsDataURL(file)
    }
  }

  const removeLawSchoolDiploma = () => {
    setLawSchoolDiplomaFile(null)
    setLawSchoolDiplomaUrl('')
  }

  const removeLawyerLicense = () => {
    setLawyerLicenseFile(null)
    setLawyerLicenseUrl('')
  }

  // 연도, 월, 일 옵션 생성
  const yearOptions = Array.from({ length: 30 }, (_, i) => ({
    value: (2024 - i).toString(),
    label: (2024 - i).toString(),
  }))

  const monthOptions = Array.from({ length: 12 }, (_, i) => ({
    value: (i + 1).toString().padStart(2, '0'),
    label: (i + 1).toString().padStart(2, '0'),
  }))

  const dayOptions = Array.from({ length: 31 }, (_, i) => ({
    value: (i + 1).toString().padStart(2, '0'),
    label: (i + 1).toString().padStart(2, '0'),
  }))

  return (
    <Modal
      title='변호사 승인 정보'
      open={open}
      onCancel={handleCancel}
      width={700}
      footer={
        <>
          <Button onClick={handleCancel} disabled={isSubmitting}>
            취소
          </Button>
          <Button
            type='primary'
            onClick={handleSubmit}
            loading={isSubmitting}
            disabled={!hasChanges() || isSubmitting}
            style={{ backgroundColor: '#20bf62', borderColor: '#20bf62' }}
          >
            저장하기
          </Button>
        </>
      }
    >
      <div className={styles.lawyerApprovalModal}>
        <div className={styles.formRow}>
          <label>로스쿨 졸업장</label>
          <div>
            <div className={styles.fileUploadContainer}>
              <Input
                placeholder='첨부파일을 선택해주세요'
                value={lawSchoolDiplomaFile ? lawSchoolDiplomaFile.name : ''}
                readOnly
              />
              <Button
                icon={<UploadOutlined />}
                onClick={() => document.getElementById('lawSchoolDiplomaInput')?.click()}
              >
                첨부파일
              </Button>
              <input
                type='file'
                id='lawSchoolDiplomaInput'
                accept='image/*,.pdf,.doc,.docx'
                onChange={handleLawSchoolDiplomaUpload}
                style={{ display: 'none' }}
              />
            </div>
            {lawSchoolDiplomaUrl && !lawSchoolDiplomaFile && (
              <div style={{ marginTop: '8px' }}>
                <span
                  style={{ color: 'red', textDecoration: 'underline', fontSize: '14px', cursor: 'pointer' }}
                  onClick={() => window.open(lawSchoolDiplomaUrl, '_blank')}
                >
                  {lawSchoolDiplomaUrl.split('/').pop() || '기존 파일'}
                </span>
                <CloseOutlined
                  style={{ marginLeft: '8px', fontSize: '12px', color: 'red', cursor: 'pointer' }}
                  onClick={removeLawSchoolDiploma}
                />
              </div>
            )}
            {lawSchoolDiplomaFile && (
              <div style={{ marginTop: '8px' }}>
                <span style={{ color: '#52c41a', fontSize: '14px' }}>
                  새 파일: {lawSchoolDiplomaFile.name}
                  <CloseOutlined
                    style={{ marginLeft: '8px', fontSize: '12px', color: '#52c41a' }}
                    onClick={removeLawSchoolDiploma}
                  />
                </span>
              </div>
            )}
          </div>
        </div>

        <div className={styles.formRow}>
          <label>변호사 자격증</label>
          <div>
            <div className={styles.fileUploadContainer}>
              <Input
                placeholder='첨부파일을 선택해주세요'
                value={lawyerLicenseFile ? lawyerLicenseFile.name : ''}
                readOnly
              />
              <Button icon={<UploadOutlined />} onClick={() => document.getElementById('lawyerLicenseInput')?.click()}>
                첨부파일
              </Button>
              <input
                type='file'
                id='lawyerLicenseInput'
                accept='image/*,.pdf,.doc,.docx'
                onChange={handleLawyerLicenseUpload}
                style={{ display: 'none' }}
              />
            </div>
            {lawyerLicenseUrl && !lawyerLicenseFile && (
              <div style={{ marginTop: '8px' }}>
                <span
                  style={{ color: 'red', textDecoration: 'underline', fontSize: '14px', cursor: 'pointer' }}
                  onClick={() => window.open(lawyerLicenseUrl, '_blank')}
                >
                  {lawyerLicenseUrl.split('/').pop() || '기존 파일'}
                </span>
                <CloseOutlined
                  style={{ marginLeft: '8px', fontSize: '12px', color: 'red', cursor: 'pointer' }}
                  onClick={removeLawyerLicense}
                />
              </div>
            )}
            {lawyerLicenseFile && (
              <div style={{ marginTop: '8px' }}>
                <span style={{ color: '#52c41a', fontSize: '14px' }}>
                  새 파일: {lawyerLicenseFile.name}
                  <CloseOutlined
                    style={{ marginLeft: '8px', fontSize: '12px', color: '#52c41a' }}
                    onClick={removeLawyerLicense}
                  />
                </span>
              </div>
            )}
          </div>
        </div>

        <div className={styles.formRow}>
          <label>변호사 합격일자</label>
          <div className={styles.dateContainer}>
            <Select
              placeholder='연도 선택'
              value={passingYear}
              onChange={setPassingYear}
              options={yearOptions}
              style={{ width: 120 }}
            />
            <Select
              placeholder='월'
              value={passingMonth}
              onChange={setPassingMonth}
              options={monthOptions}
              style={{ width: 80 }}
            />
            <Select
              placeholder='일'
              value={passingDay}
              onChange={setPassingDay}
              options={dayOptions}
              style={{ width: 80 }}
            />
          </div>
        </div>

        <div className={styles.formRow}>
          <label>승인 여부</label>
          <Radio.Group value={approvalStatus} onChange={e => setApprovalStatus(e.target.value)}>
            <Space direction='vertical'>
              <Radio value='pending'>대기</Radio>
              <Radio value='approved'>승인 완료</Radio>
            </Space>
          </Radio.Group>
        </div>
      </div>
    </Modal>
  )
}

export default LawyerApprovalModal

import { useState, useEffect } from 'react'
import { Modal, Space, Input, Button, Table, message } from 'antd'
import { useLawyerSearch } from '@/hooks/queries/useLawyer'

interface LawyerSearchModalProps {
  open: boolean
  onCancel: () => void
  onSelect: (lawyer: any) => void
  initialSearchQuery?: string
}

const LawyerSearchModal = ({ open, onCancel, onSelect, initialSearchQuery = '' }: LawyerSearchModalProps) => {
  const [modalSearchQuery, setModalSearchQuery] = useState('')
  const [searchTrigger, setSearchTrigger] = useState({ query: '', trigger: 0 })

  // Reset search when modal opens
  useEffect(() => {
    if (open) {
      setModalSearchQuery(initialSearchQuery)
      if (initialSearchQuery) {
        setSearchTrigger({ query: initialSearchQuery, trigger: Date.now() })
      }
    }
  }, [open, initialSearchQuery])

  // API hook
  const { data: searchData, isLoading } = useLawyerSearch({
    searchQuery: searchTrigger.query,
    searchType: 'lawyerName',
  })

  const handleModalSearch = () => {
    if (modalSearchQuery.trim()) {
      setSearchTrigger({ query: modalSearchQuery, trigger: Date.now() })
    }
  }

  const handleLawyerSelect = (lawyerId: number) => {
    const lawyers = searchData?.lawyerSearchResults || []
    const selected = lawyers.find(lawyer => lawyer.lawyerId === lawyerId)
    if (selected) {
      onSelect(selected)
      message.success('변호사가 선택되었습니다.')
      handleClose()
    }
  }

  const handleClose = () => {
    setModalSearchQuery('')
    setSearchTrigger({ query: '', trigger: 0 })
    onCancel()
  }

  const columns = [
    {
      title: '변호사 사진',
      dataIndex: 'lawyerProfileImage',
      key: 'lawyerProfileImage',
      width: 100,
      render: (image: string | null, record: any) => (
        <div
          style={{
            width: 60,
            height: 60,
            backgroundColor: '#f0f0f0',
            borderRadius: '50%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: 24,
            color: '#999',
          }}
        >
          {image ? (
            <img
              src={image}
              alt={record.lawyerName}
              style={{ width: '100%', height: '100%', borderRadius: '50%', objectFit: 'cover' }}
            />
          ) : (
            <span>👤</span>
          )}
        </div>
      ),
    },
    {
      title: '변호사명',
      dataIndex: 'lawyerName',
      key: 'lawyerName',
      width: 150,
    },
    {
      title: '소속',
      dataIndex: 'lawyerLawfirmName',
      key: 'lawyerLawfirmName',
      render: (value: string | null) => value || '-',
    },
    {
      title: '가입일자',
      dataIndex: 'lawyerCreatedAt',
      key: 'lawyerCreatedAt',
      width: 120,
      render: (value: string) => {
        if (!value) return '-'
        const date = new Date(value)
        return `${date.getFullYear()}.${String(date.getMonth() + 1).padStart(2, '0')}.${String(date.getDate()).padStart(
          2,
          '0'
        )}`
      },
    },
    {
      title: '선택',
      key: 'action',
      width: 100,
      render: (_: any, record: any) => (
        <Button
          type='primary'
          onClick={() => handleLawyerSelect(record.lawyerId)}
          style={{ backgroundColor: '#52c41a', borderColor: '#52c41a' }}
        >
          선택하기
        </Button>
      ),
    },
  ]

  return (
    <Modal title='변호사 이름 검색' open={open} onCancel={handleClose} width={900} footer={null}>
      <div style={{ marginBottom: 16 }}>
        <Space.Compact style={{ width: '100%' }}>
          <Input
            placeholder='변호사 이름을 검색해주세요'
            value={modalSearchQuery}
            onChange={e => setModalSearchQuery(e.target.value)}
            onPressEnter={handleModalSearch}
            size='large'
            style={{ flex: 1 }}
          />
          <Button type='primary' size='large' onClick={handleModalSearch} style={{ width: 100 }}>
            검색
          </Button>
        </Space.Compact>
      </div>

      <Table
        dataSource={searchData?.lawyerSearchResults || []}
        rowKey='lawyerId'
        loading={isLoading}
        pagination={false}
        locale={{ emptyText: modalSearchQuery ? '검색 결과가 없습니다.' : '변호사 이름을 검색해주세요.' }}
        columns={columns}
      />
    </Modal>
  )
}

export default LawyerSearchModal

// import styles from './multiple-image-slider.module.scss'

import Slider from 'react-slick'
import 'slick-carousel/slick/slick.css'
import 'slick-carousel/slick/slick-theme.css'
import styles from './multiple-image-slider.module.scss'

import { CSSProperties, useEffect, useRef } from 'react'

type MultipleImageSliderProps = {
  imageList: string[]
  imgHeight?: number
  dots?: boolean
  arrow?: boolean
  width?: number | string // 슬라이더 너비 prop 추가
}

interface CustomArrowProps {
  className?: string
  style?: CSSProperties
  onClick?: () => void
  type?: 'next' | 'prev'
}

const Arrow = ({ className, onClick, type }: CustomArrowProps) => (
  <div
    className={`${className} ${styles['nav-button']} ${styles[`nav-button-${type}`]}`}
    onClick={onClick}
    style={{ display: 'block', zIndex: 1 }}
  >
    {/* <SvgIcon name='slickArrow' size={16} style={{ transform: type === 'prev' ? 'rotate(180deg)' : 'rotate(0deg)' }} /> */}
  </div>
)

const MultipleImageSlider = ({
  imageList,
  imgHeight = 108,
  dots = false,
  arrow = true,
  width = '100%',
}: MultipleImageSliderProps) => {
  // 이미지 개수에 따른 설정 조정
  const hasMultipleImages = imageList.length > 1
  const sliderRef = useRef<Slider>(null)

  // 화면에 다 들어갈지 확인
  const containerWidth = typeof width === 'number' ? width : 800
  const estimatedImageWidth = 150 // 대략적인 이미지 너비
  const estimatedTotalWidth = imageList.length * estimatedImageWidth
  const needsScrolling = estimatedTotalWidth > containerWidth

  // 슬라이더 설정 - 스크롤이 필요할 때만 infinite
  const settings = {
    className: hasMultipleImages ? 'slider variable-width' : 'slider fixed-width',
    variableWidth: hasMultipleImages,
    dots: dots,
    infinite: hasMultipleImages && needsScrolling,
    centerMode: false,
    slidesToShow: 1,
    slidesToScroll: 1,
    arrows: arrow && hasMultipleImages && needsScrolling,
    nextArrow: <Arrow type='next' />,
    prevArrow: <Arrow type='prev' />,
    swipeToSlide: hasMultipleImages,
    adaptiveHeight: false,
  }

  // 슬라이더 스타일
  const sliderStyle: CSSProperties = {
    width: width,
  }

  // 동적으로 CSS 변수 설정
  useEffect(() => {
    document.documentElement.style.setProperty('--slide-height', `${imgHeight}px`)
  }, [imgHeight])

  return (
    <div className={styles.sliderWrapper} style={sliderStyle}>
      {/* @ts-ignore - react-slick type compatibility issue */}
      <Slider ref={sliderRef} {...settings}>
        {imageList.map((img, index) => (
          <div key={index} className={styles.slideItem} style={{ height: `${imgHeight}px` }}>
            <figure style={{ height: `${imgHeight}px` }}>
              <img src={img} alt='lawfirm' className={styles['img-item']} style={{ height: `${imgHeight}px` }} />
            </figure>
          </div>
        ))}
      </Slider>
    </div>
  )
}

export default MultipleImageSlider

import React from 'react'
import { menuItemsWithPermissions } from '@/constants/menu'
import { Menu, MenuProps } from 'antd'
import styles from './sidebar.module.scss'
import { useNavigate } from 'react-router-dom'
import { ROUTE_PATH } from '@/routes/routePath'

interface SidebarProps {
  collapsed?: boolean
  isTablet?: boolean
  subMenuIds?: number[]
}

const SidebarHeader = () => {
  const navigate = useNavigate()

  const handleLogout = () => {
    // 로컬스토리지와 세션스토리지 초기화
    localStorage.clear()
    sessionStorage.clear()

    // 로그인 페이지로 리다이렉트
    navigate(ROUTE_PATH.LOGIN)
  }

  return (
    <div className={styles['sidebar-header']}>
      <div className={styles['header-title']}>올바로 2.0</div>
      <div className={styles['header-subtitle']}>통합관리자</div>
      <div className={styles['header-actions']}>
        <button className={styles['logout-btn']} onClick={handleLogout}>
          [로그아웃]
        </button>
        <a href='https://v2.allbarlaw.com/' target='_blank' rel='noopener noreferrer' className={styles['home-link']}>
          홈페이지 바로가기
        </a>
      </div>
    </div>
  )
}

const Sidebar: React.FC<SidebarProps> = ({ collapsed = false, isTablet = false, subMenuIds = [] }) => {
  const navigate = useNavigate()

  const onClick: MenuProps['onClick'] = e => {
    navigate(e.key)
  }

  // 권한에 따라 메뉴 아이템 필터링
  const filterMenuItems = (items: any[]): any[] => {
    return items
      .map(item => {
        if (item.children) {
          const filteredChildren = item.children
            .filter((child: any) => {
              // 서브메뉴가 권한 ID를 가지고 있는지 확인
              return subMenuIds.includes(child.permissionId)
            })
            .map((child: any) => {
              // permissionId를 제거하고 나머지 속성만 반환
              const { permissionId, ...rest } = child
              return rest
            })

          if (filteredChildren.length > 0) {
            return {
              ...item,
              children: filteredChildren,
            }
          }
          return null
        }
        return item
      })
      .filter(Boolean)
  }

  const filteredMenuItems = filterMenuItems(menuItemsWithPermissions)
  const alwaysOpenKeys = ['admin', 'category', 'member', 'lawyer', 'content', 'chat', 'board', 'ad', 'statistics']

  return (
    <div
      className={`${styles.sidebar} ${collapsed && isTablet ? styles.collapsed : ''} ${isTablet ? styles.tablet : ''}`}
    >
      <SidebarHeader />
      <Menu
        onClick={onClick}
        mode='inline'
        items={filteredMenuItems}
        openKeys={alwaysOpenKeys}
        onOpenChange={() => {}}
      />
    </div>
  )
}

