import React, { useState, useRef, useEffect } from 'react'
import styles from './ai-recommender-content-slider.module.scss'

type AiRecommenderContentSliderProps = {
  title: string
  children: React.ReactNode
  className?: string
  autoPlay?: boolean
  autoPlayInterval?: number
  itemsPerSlide?: number
}

const AiRecommenderContentSlider = ({
  title,
  children,
  className,
  autoPlay = false,
  autoPlayInterval = 3000,
  itemsPerSlide = 1,
}: AiRecommenderContentSliderProps) => {
  const [currentSlide, setCurrentSlide] = useState(0)
  const [isDragging, setIsDragging] = useState(false)
  const [startX, setStartX] = useState(0)
  const [translateX, setTranslateX] = useState(0)
  const [isPaused, setIsPaused] = useState(false)
  const [isTransitioning, setIsTransitioning] = useState(true)
  const sliderRef = useRef<HTMLDivElement>(null)
  const autoPlayRef = useRef<ReturnType<typeof setInterval> | null>(null)

  const childrenArray = React.Children.toArray(children)
  const totalSlides = Math.ceil(childrenArray.length / itemsPerSlide)

  const goToNextSlide = () => {
    setCurrentSlide(prev => (prev + 1) % totalSlides)
  }

  useEffect(() => {
    if (autoPlay && !isPaused && !isDragging && totalSlides > 1) {
      autoPlayRef.current = setInterval(goToNextSlide, autoPlayInterval)
    } else {
      if (autoPlayRef.current) {
        clearInterval(autoPlayRef.current)
        autoPlayRef.current = null
      }
    }

    return () => {
      if (autoPlayRef.current) {
        clearInterval(autoPlayRef.current)
      }
    }
  }, [autoPlay, isPaused, isDragging, autoPlayInterval, totalSlides, currentSlide])

  const handleSlideChange = (index: number) => {
    // 페이지네이션 클릭 시에도 앞으로만 이동 (순환)
    if (index >= 0 && index < totalSlides) {
      setIsTransitioning(true)
      setCurrentSlide(index)
      setTranslateX(0)
    }
  }

  const handleStart = (clientX: number) => {
    setIsDragging(true)
    setStartX(clientX)
  }

  const handleMove = (clientX: number) => {
    if (!isDragging) return
    const diff = clientX - startX
    // 오른쪽으로 드래그하는 것을 방지 (이전으로 가지 않음)
    if (diff > 0) {
      setTranslateX(0)
    } else {
      setTranslateX(diff)
    }
  }

  const handleEnd = () => {
    if (!isDragging) return
    setIsDragging(false)

    if (Math.abs(translateX) > 50) {
      if (translateX < 0) {
        // 왼쪽으로 스와이프 - 다음 슬라이드로만 이동
        handleSlideChange((currentSlide + 1) % totalSlides)
      }
      // 오른쪽 스와이프는 무시 (이전으로 가지 않음)
    }
    setTranslateX(0)
  }

  const handleMouseDown = (e: React.MouseEvent) => {
    e.preventDefault()
    handleStart(e.clientX)
  }

  const handleMouseMove = (e: React.MouseEvent) => {
    handleMove(e.clientX)
  }

  const handleMouseUp = () => {
    handleEnd()
  }

  const handleTouchStart = (e: React.TouchEvent) => {
    handleStart(e.touches[0].clientX)
  }

  const handleTouchMove = (e: React.TouchEvent) => {
    handleMove(e.touches[0].clientX)
  }

  const handleTouchEnd = () => {
    handleEnd()
  }

  const handleMouseEnter = () => {
    if (autoPlay) {
      setIsPaused(true)
    }
  }

  const handleMouseLeave = () => {
    if (autoPlay) {
      setIsPaused(false)
    }
  }

  useEffect(() => {
    const handleGlobalMouseMove = (e: MouseEvent) => {
      if (isDragging) {
        handleMove(e.clientX)
      }
    }

    const handleGlobalMouseUp = () => {
      if (isDragging) {
        handleEnd()
      }
    }

    if (isDragging) {
      document.addEventListener('mousemove', handleGlobalMouseMove)
      document.addEventListener('mouseup', handleGlobalMouseUp)
    }

    return () => {
      document.removeEventListener('mousemove', handleGlobalMouseMove)
      document.removeEventListener('mouseup', handleGlobalMouseUp)
    }
  }, [isDragging, startX, translateX, currentSlide])

  return (
    <div className={`${styles.wrapper} ${className || ''}`}>
      <div
        className={styles.container}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <div className={styles.contentWrapper}>
          <h3 className={styles.title}>{title}</h3>

          <div
            className={styles.sliderWrapper}
            ref={sliderRef}
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onTouchStart={handleTouchStart}
            onTouchMove={handleTouchMove}
            onTouchEnd={handleTouchEnd}
          >
            <div
              className={styles.sliderTrack}
              style={{
                transform: `translateX(calc(-${currentSlide * 100}% + ${translateX}px))`,
                transition: isDragging ? 'none' : isTransitioning ? 'transform 0.3s ease' : 'none',
              }}
            >
              {Array.from({ length: totalSlides }).map((_, slideIndex) => (
                <div key={slideIndex} className={styles.slideGroup}>
                  {childrenArray.slice(slideIndex * itemsPerSlide, (slideIndex + 1) * itemsPerSlide).map((child, index) => (
                    <div key={`${slideIndex}-${index}`} className={styles.slideItem} style={{ flex: `0 0 calc(${100 / itemsPerSlide}% - ${itemsPerSlide > 1 ? '8px' : '0px'})` }}>
                      {child}
                    </div>
                  ))}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {totalSlides > 1 && (
        <div className={styles.pagination}>
          {Array.from({ length: totalSlides }).map((_, index) => (
            <button
              key={index}
              className={`${styles.paginationDot} ${index === currentSlide ? styles.active : ''}`}
              onClick={() => handleSlideChange(index)}
              aria-label={`Go to slide ${index + 1}`}
            />
          ))}
        </div>
      )}
    </div>
  )
}

export default AiRecommenderContentSlider

import React, { useState, useRef } from 'react'
import Slider, { Settings } from 'react-slick'
import styles from './image-slider.module.scss'
import 'slick-carousel/slick/slick.css'
import 'slick-carousel/slick/slick-theme.css'

export interface ImageItem {
  id: string | number
  src: string
  alt?: string
  title?: string
  description?: string
  onClick?: () => void
}

export interface ImageSliderProps {
  images: string[] | ImageItem[] // 문자열 배열 또는 객체 배열 둘 다 지원
  className?: string
  width?: string | number
  height?: string | number
  sliderSettings?: Partial<Settings>
  showTitle?: boolean
  showDescription?: boolean
  imageObjectFit?: 'cover' | 'contain' | 'fill' | 'none' | 'scale-down'
  loading?: 'lazy' | 'eager'
  // 추가 확장성을 위한 props
  renderCustomContent?: (_item: ImageItem, _index: number) => React.ReactNode
  onSlideChange?: (_currentSlide: number) => void
  onImageClick?: (_src: string, _index: number) => void // 간단한 클릭 핸들러
  customArrows?: {
    prevArrow?: React.ComponentType<any>
    nextArrow?: React.ComponentType<any>
  }
  // 커스텀 닷 관련
  customDots?: boolean
  renderCustomDot?: (_index: number, _isActive: boolean, _onClick: () => void) => React.ReactNode
}

const defaultSettings: Settings = {
  dots: true,
  infinite: true,
  speed: 500,
  slidesToShow: 1,
  slidesToScroll: 1,
  autoplay: false,
  autoplaySpeed: 3000,
  pauseOnHover: true,
  arrows: true,
  adaptiveHeight: true,
  lazyLoad: 'ondemand',
}

const ImageSlider: React.FC<ImageSliderProps> = ({
  images,
  className = '',
  width = '100%',
  height = 'auto',
  sliderSettings = {},
  showTitle = false,
  showDescription = false,
  // 사용하지 않는 props는 _ prefix
  imageObjectFit: _imageObjectFit = 'cover',
  loading: _loading = 'lazy',
  renderCustomContent: _renderCustomContent,
  onSlideChange,
  onImageClick,
  customArrows,
  customDots = false,
  renderCustomDot,
}) => {
  const [currentSlide, setCurrentSlide] = useState(0)
  const sliderRef = useRef<Slider>(null)

  // 문자열 배열을 ImageItem 배열로 변환하는 함수
  const normalizeImages = (images: string[] | ImageItem[]): ImageItem[] => {
    return images.map((item, index) => {
      if (typeof item === 'string') {
        return {
          id: index,
          src: item,
          alt: `이미지 ${index + 1}`,
          onClick: onImageClick ? () => onImageClick(item, index) : undefined,
        }
      }
      return item
    })
  }

  const normalizedImages = normalizeImages(images)

  // 슬라이드 변경 핸들러
  const handleSlideChange = (current: number) => {
    setCurrentSlide(current)
    onSlideChange?.(current)
  }

  // 닷 클릭 핸들러
  const handleDotClick = (index: number) => {
    sliderRef.current?.slickGoTo(index)
  }

  // Slick 설정 병합
  const mergedSettings: Settings = {
    ...defaultSettings,
    ...sliderSettings,
    dots: customDots ? false : sliderSettings.dots ?? defaultSettings.dots, // 커스텀 닷 사용 시 기본 닷 비활성화
    afterChange: (current: number) => {
      handleSlideChange(current)
      // 기존 afterChange 콜백도 유지
      sliderSettings.afterChange?.(current)
    },
    ...(customArrows && {
      prevArrow: customArrows.prevArrow ? <customArrows.prevArrow /> : defaultSettings.prevArrow,
      nextArrow: customArrows.nextArrow ? <customArrows.nextArrow /> : defaultSettings.nextArrow,
    }),
  }

  // 스타일 객체 생성
  const containerStyle: React.CSSProperties = {
    width: typeof width === 'number' ? `${width}px` : width,
    height:
      customDots && height !== 'auto'
        ? typeof height === 'number'
          ? `${height + 24}px` // 이미지 높이 + 닷 영역 (8 + 16)
          : `calc(${height} + 24px)`
        : typeof height === 'number'
        ? `${height}px`
        : height,
  }

  const renderSlideContent = (_item: ImageItem, _index: number) => {
    return (
      <div className={styles['slide-content']}>
        <img 
          src={_item.src} 
          alt={_item.alt || `이미지 ${_index + 1}`}
          className={styles['slide-image']}
          style={{ 
            width: '100%',
            height: typeof height === 'number' ? `${height}px` : height,
            objectFit: _imageObjectFit 
          }}
          loading={_loading}
          onClick={_item.onClick}
        />
        {showTitle && _item.title && <h3 className={styles.title}>{_item.title}</h3>}
        {showDescription && _item.description && <p className={styles.description}>{_item.description}</p>}
      </div>
    )
  }

  // 기본 커스텀 닷 렌더링
  const renderDefaultCustomDot = (_index: number, _isActive: boolean, _onClick: () => void) => (
    <button
      key={_index}
      className={`${styles['custom-dot']} ${_isActive ? styles.active : ''}`}
      onClick={_onClick}
      aria-label={`슬라이드 ${_index + 1}로 이동`}
    />
  )

  if (!images || images.length === 0) {
    return (
      <div className={`${styles['image-slider-empty']} ${className}`}>
        <p>표시할 이미지가 없습니다.</p>
      </div>
    )
  }

  return (
    <div
      className={`${styles['image-slider-container']} ${className} ${
        customDots ? styles['custom-dots-container'] : ''
      }`}
      style={containerStyle}
    >
      {/* @ts-ignore - react-slick type compatibility issue */}
      <Slider {...mergedSettings} className={styles['image-slider']} ref={sliderRef}>
        {normalizedImages.map((item, index) => (
          <div key={item.id} className={styles['slide-wrapper']}>
            {renderSlideContent(item, index)}
          </div>
        ))}
      </Slider>

      {/* 커스텀 닷 렌더링 */}
      {customDots && normalizedImages.length > 1 && (
        <div className={styles['custom-dots-wrapper']}>
          {normalizedImages.map((_, index) => {
            const isActive = index === currentSlide
            const onClick = () => handleDotClick(index)

            return renderCustomDot
              ? renderCustomDot(index, isActive, onClick)
              : renderDefaultCustomDot(index, isActive, onClick)
          })}
        </div>
      )}
    </div>
  )
}

