import React, { useState } from 'react'
import { Button, Input, Modal, message } from 'antd'
import { UploadOutlined } from '@ant-design/icons'
import styles from './mainCategoryEditor.module.scss'
import { useFileUpload } from '@/hooks/useFileUpload'
import { useCreateCategory, useUpdateCategory } from '@/hooks/queries/useCategory'

interface MainCategoryEditorProps {
  title: string
  open: boolean
  onCancel: () => void
  onSubmit: (data: { name: string; onImage: File | null; offImage: File | null; categoryId?: number }) => void
  defaultValues?: {
    id?: number // 카테고리 ID 추가 (수정 시 필요)
    name?: string
    onImage?: string
    offImage?: string
  }
}

const MainCategoryEditor: React.FC<MainCategoryEditorProps> = ({ title, open, onCancel, onSubmit, defaultValues }) => {
  const [categoryName, setCategoryName] = useState('')
  const [onImageFile, setOnImageFile] = useState<File | null>(null)
  const [offImageFile, setOffImageFile] = useState<File | null>(null)
  const [onImagePreview, setOnImagePreview] = useState<string>('')
  const [offImagePreview, setOffImagePreview] = useState<string>('')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const isEditMode = title.includes('수정') || title.includes('edit')

  const { uploadFile } = useFileUpload()
  const createCategoryMutation = useCreateCategory()
  const updateCategoryMutation = useUpdateCategory()

  React.useEffect(() => {
    if (open) {
      setCategoryName(defaultValues?.name || '')
      setOnImageFile(null)
      setOffImageFile(null)
      setOnImagePreview(defaultValues?.onImage || '')
      setOffImagePreview(defaultValues?.offImage || '')
    }
  }, [open, defaultValues])

  const handleSubmit = async () => {
    if (!categoryName.trim()) {
      message.warning('대분류 이름을 입력해주세요.')
      return
    }

    // 수정 모드에서는 이미지가 없어도 기존 이미지 사용
    if (!isEditMode && (!onImageFile || !offImageFile)) {
      message.warning('ON 이미지와 OFF 이미지를 모두 등록해주세요.')
      return
    }

    if (isEditMode && !defaultValues?.id) {
      message.error('카테고리 ID가 없습니다.')
      return
    }

    try {
      setIsSubmitting(true)

      let onImageUrl = defaultValues?.onImage || ''
      let offImageUrl = defaultValues?.offImage || ''

      // 새 이미지가 있으면 업로드
      if (onImageFile || offImageFile) {
        const uploadPromises = []

        if (onImageFile) {
          uploadPromises.push(
            uploadFile(onImageFile, {
              folder: 'category-clicked',
              allowedTypes: ['image/jpeg', 'image/png', 'image/gif', 'image/webp'],
              maxSize: 5,
            })
          )
        }

        if (offImageFile) {
          uploadPromises.push(
            uploadFile(offImageFile, {
              folder: 'category-nonClicked',
              allowedTypes: ['image/jpeg', 'image/png', 'image/gif', 'image/webp'],
              maxSize: 5,
            })
          )
        }

        const uploadResults = await Promise.all(uploadPromises)

        // 업로드 결과 처리
        if (onImageFile && uploadResults[0]) {
          onImageUrl = uploadResults[0].fileUrl
        }
        if (offImageFile) {
          const resultIndex = onImageFile ? 1 : 0
          if (uploadResults[resultIndex]) {
            offImageUrl = uploadResults[resultIndex].fileUrl
          }
        }
      }

      if (isEditMode) {
        // 수정 모드
        await updateCategoryMutation.mutateAsync({
          categoryId: defaultValues!.id!,
          category: {
            categoryName: categoryName,
            categoryImageUrl: offImageUrl, // OFF 이미지가 기본 이미지
            categoryClickedImageUrl: onImageUrl, // ON 이미지가 클릭된 이미지
          },
        })
        message.success('대분류가 성공적으로 수정되었습니다.')
      } else {
        // 생성 모드
        const response = await createCategoryMutation.mutateAsync({
          categoryName: categoryName,
          categoryImageUrl: offImageUrl, // OFF 이미지가 기본 이미지
          categoryClickedImageUrl: onImageUrl, // ON 이미지가 클릭된 이미지
        })
        message.success('대분류가 성공적으로 등록되었습니다.')

        // 성공 시 부모 컴포넌트의 onSubmit 호출 (생성된 카테고리 ID 포함)
        onSubmit({
          name: categoryName,
          onImage: onImageFile,
          offImage: offImageFile,
          categoryId: response.data.categoryId, // 새로 생성된 카테고리 ID 추가
        })
      }

      // 수정 모드일 때는 ID 없이 호출
      if (isEditMode) {
        onSubmit({
          name: categoryName,
          onImage: onImageFile,
          offImage: offImageFile,
        })
      }

      // 초기화
      setCategoryName('')
      setOnImageFile(null)
      setOffImageFile(null)
      setOnImagePreview('')
      setOffImagePreview('')
    } catch (error) {
      console.error('카테고리 등록 실패:', error)
      message.error(error instanceof Error ? error.message : '카테고리 등록에 실패했습니다.')
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleCancel = () => {
    setCategoryName('')
    setOnImageFile(null)
    setOffImageFile(null)
    setOnImagePreview('')
    setOffImagePreview('')
    onCancel()
  }

  const handleOnImageChange = (file: File) => {
    setOnImageFile(file)
    // 미리보기를 위한 URL 생성
    const reader = new FileReader()
    reader.onload = e => {
      setOnImagePreview(e.target?.result as string)
    }
    reader.readAsDataURL(file)
  }

  const handleOffImageChange = (file: File) => {
    setOffImageFile(file)
    // 미리보기를 위한 URL 생성
    const reader = new FileReader()
    reader.onload = e => {
      setOffImagePreview(e.target?.result as string)
    }
    reader.readAsDataURL(file)
  }

  const handleOnImageUpload = (info: any) => {
    const file = info.target.files?.[0]
    if (file) {
      handleOnImageChange(file)
    }
  }

  const handleOffImageUpload = (info: any) => {
    const file = info.target.files?.[0]
    if (file) {
      handleOffImageChange(file)
    }
  }

  return (
    <Modal
      title={title}
      open={open}
      onCancel={handleCancel}
      width={700}
      footer={
        <>
          <Button onClick={handleCancel}>취소</Button>
          <Button
            type='primary'
            onClick={handleSubmit}
            loading={isSubmitting}
            disabled={!categoryName.trim() || (!isEditMode && (!onImageFile || !offImageFile)) || isSubmitting}
            style={{ backgroundColor: '#20bf62', borderColor: '#20bf62' }}
          >
            저장
          </Button>
        </>
      }
    >
      <div className={styles.mainCategoryEditor}>
        <div className={styles.formRow}>
          <label>대분류 이름</label>
          <Input
            placeholder='대분류 이름을 입력해주세요.'
            value={categoryName}
            onChange={e => setCategoryName(e.target.value)}
          />
        </div>

        <div className={styles.formRow}>
          <label>ON 이미지 등록</label>
          <div className={styles.imageUploadContainer}>
            <div className={styles.imagePreview}>
              {onImagePreview ? (
                <img src={onImagePreview} alt='ON 이미지 미리보기' />
              ) : (
                <div className={styles.noImage}>이미지가 없습니다</div>
              )}
            </div>
            <div className={styles.uploadButtonContainer}>
              <input
                type='file'
                id='onImageInput'
                accept='image/*'
                onChange={handleOnImageUpload}
                style={{ display: 'none' }}
              />
              <Button icon={<UploadOutlined />} onClick={() => document.getElementById('onImageInput')?.click()}>
                이미지 선택
              </Button>
            </div>
          </div>
        </div>

        <div className={styles.formRow}>
          <label>OFF 이미지 등록</label>
          <div className={styles.imageUploadContainer}>
            <div className={styles.imagePreview}>
              {offImagePreview ? (
                <img src={offImagePreview} alt='OFF 이미지 미리보기' />
              ) : (
                <div className={styles.noImage}>이미지가 없습니다</div>
              )}
            </div>
            <div className={styles.uploadButtonContainer}>
              <input
                type='file'
                id='offImageInput'
                accept='image/*'
                onChange={handleOffImageUpload}
                style={{ display: 'none' }}
              />
              <Button icon={<UploadOutlined />} onClick={() => document.getElementById('offImageInput')?.click()}>
                이미지 선택
              </Button>
            </div>
          </div>
        </div>
      </div>
    </Modal>
  )
}

export default MainCategoryEditor

import { useState, forwardRef, useImperativeHandle, useEffect } from 'react'
import { Button, Input, message, Spin } from 'antd'
import { PlusOutlined, DeleteOutlined, MenuOutlined } from '@ant-design/icons'
import DraggableTable from '@/components/draggableTable/DraggableTable'
import { LawyerActivity } from '@/types/lawyerTypes'
import { useLawyerActivity } from '@/hooks/queries/useLawyer'
import styles from './lawyerEditActivity.module.scss'

const { TextArea } = Input

interface ActivityItem extends LawyerActivity {
  id: string
}

export interface LawyerEditActivityRef {
  getFormData: () => LawyerActivity[]
}

interface LawyerEditActivityProps {
  lawyerId?: string
}

const LawyerEditActivity = forwardRef<LawyerEditActivityRef, LawyerEditActivityProps>(({ lawyerId }, ref) => {
  const { data: activityDataFromAPI, isLoading } = useLawyerActivity(Number(lawyerId))

  const [activityData, setActivityData] = useState<ActivityItem[]>([])
  const [isInitialized, setIsInitialized] = useState(false)

  // API 데이터로 초기화
  useEffect(() => {
    if (activityDataFromAPI && !isInitialized) {
      // activityDataFromAPI가 배열인지 확인
      const dataArray = Array.isArray(activityDataFromAPI) ? activityDataFromAPI : []

      if (dataArray.length > 0) {
        const initialData = dataArray.map((item: LawyerActivity, index: number) => ({
          ...item,
          id: `api-${index}`,
        }))
        setActivityData(initialData)
      } else {
        // 데이터가 비어있으면 빈 배열 유지
        setActivityData([])
      }
      setIsInitialized(true)
    } else if (!activityDataFromAPI && !isLoading && !isInitialized) {
      // API 호출 실패 또는 데이터가 없는 경우 빈 배열
      setActivityData([])
      setIsInitialized(true)
    }
  }, [activityDataFromAPI, isLoading, isInitialized])

  const [selectedActivity, setSelectedActivity] = useState<ActivityItem | null>(null)
  const [contentValue, setContentValue] = useState('')
  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null)
  const [editingCategoryName, setEditingCategoryName] = useState('')

  // 선택된 항목이 변경될 때 content 업데이트
  const handleActivityClick = (record: ActivityItem) => {
    setSelectedActivity(record)
    setContentValue(record.lawyerActivityContent)
  }

  // 카테고리 이름 더블클릭 핸들러
  const handleCategoryDoubleClick = (record: ActivityItem) => {
    setEditingCategoryId(record.id)
    setEditingCategoryName(record.lawyerActivityCategoryName)
  }

  // 카테고리 이름 인라인 편집 저장
  const handleCategoryNameSave = (id: string) => {
    setActivityData(prev =>
      prev.map(item => (item.id === id ? { ...item, lawyerActivityCategoryName: editingCategoryName } : item))
    )
    setEditingCategoryId(null)
    setEditingCategoryName('')

    // 선택된 항목이 편집 중인 항목이라면 업데이트
    if (selectedActivity?.id === id) {
      setSelectedActivity(prev => (prev ? { ...prev, lawyerActivityCategoryName: editingCategoryName } : null))
    }
    message.success('카테고리 이름이 변경되었습니다.')
  }

  // 카테고리 이름 인라인 편집 취소
  const handleCategoryNameCancel = () => {
    setEditingCategoryId(null)
    setEditingCategoryName('')
  }

  // 우측 테이블 컬럼
  const columns = [
    {
      title: '활동 분류',
      dataIndex: 'lawyerActivityCategoryName',
      render: (text: string, record: ActivityItem) => (
        <div className={styles.categoryCell}>
          {editingCategoryId === record.id ? (
            <Input
              value={editingCategoryName}
              onChange={e => setEditingCategoryName(e.target.value)}
              onPressEnter={() => handleCategoryNameSave(record.id)}
              onBlur={() => handleCategoryNameSave(record.id)}
              onKeyDown={e => {
                if (e.key === 'Escape') {
                  handleCategoryNameCancel()
                }
              }}
              autoFocus
              size='small'
              style={{ width: '100%' }}
            />
          ) : (
            <span
              onDoubleClick={() => handleCategoryDoubleClick(record)}
              style={{ cursor: 'pointer', width: '100%', display: 'block' }}
              title='더블클릭하여 편집'
            >
              {text}
            </span>
          )}
        </div>
      ),
    },
    {
      title: '이동',
      width: 50,
      align: 'center' as const,
      render: () => <MenuOutlined style={{ cursor: 'grab', color: '#999' }} />,
    },
    {
      title: '삭제',
      width: 50,
      align: 'center' as const,
      render: (_: any, record: ActivityItem) => (
        <Button
          type='text'
          size='small'
          danger
          icon={<DeleteOutlined />}
          onClick={e => {
            e.stopPropagation()
            handleDelete(record.id)
          }}
        />
      ),
    },
  ]

  // 순서 변경 핸들러
  const handleChangeOrder = (newData: ActivityItem[]) => {
    const reorderedData = newData.map((item, index) => ({
      ...item,
      lawyerActivityDisplayOrder: index + 1,
    }))
    setActivityData(reorderedData)
  }

  // 카테고리 추가
  const handleAdd = () => {
    const newItem: ActivityItem = {
      id: Date.now().toString(),
      lawyerActivityCategoryName: '새 카테고리',
      lawyerActivityContent: '',
      lawyerActivityDisplayOrder: activityData.length + 1,
    }
    setActivityData(prev => [...prev, newItem])
    setSelectedActivity(newItem)
    setContentValue('')
    message.success('새 카테고리가 추가되었습니다.')
  }

  // 카테고리 삭제
  const handleDelete = (id: string) => {
    setActivityData(prev => {
      const filtered = prev.filter(item => item.id !== id)
      return filtered.map((item, index) => ({
        ...item,
        lawyerActivityDisplayOrder: index + 1,
      }))
    })

    if (selectedActivity?.id === id) {
      setSelectedActivity(null)
      setContentValue('')
    }

    message.success('삭제되었습니다.')
  }

  useImperativeHandle(ref, () => ({
    getFormData: () => activityData.map(({ id, ...rest }) => rest),
  }))

  if (isLoading) {
    return (
      <div className={styles.lawyerEditActivity}>
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '400px' }}>
          <Spin size='large' />
        </div>
      </div>
    )
  }

  return (
    <div className={styles.lawyerEditActivity}>
      <section className={styles.wrapper}>
        {/* 좌측: 카테고리 리스트 */}
        <article className={styles.leftPanel}>
          <div className={styles.tableWrapper}>
            <DraggableTable
              columns={columns}
              dataSource={activityData}
              rowKey='id'
              onChangeOrder={handleChangeOrder}
              onRowClick={handleActivityClick}
            />
          </div>

          <div className={styles.addButtonWrapper}>
            <Button icon={<PlusOutlined />} onClick={handleAdd} size='middle' style={{ width: '100%' }}>
              추가
            </Button>
          </div>
        </article>

        {/* 우측: 선택된 카테고리 내용 편집 */}
        <article className={styles.rightPanel}>
          <div className={styles.panelHeader}>
            <h3 className={styles.title}>
              {selectedActivity ? <>활동분류 &gt; {selectedActivity.lawyerActivityCategoryName}</> : '활동 내용'}
            </h3>
          </div>

          {selectedActivity ? (
            <div className={styles.editorContent}>
              <div className={styles.formGroup}>
                <TextArea
                  value={contentValue}
                  onChange={e => setContentValue(e.target.value)}
                  onBlur={() => {
                    // 내용이 변경되었을 때 자동 저장
                    if (selectedActivity && contentValue !== selectedActivity.lawyerActivityContent) {
                      setActivityData(prev =>
                        prev.map(item =>
                          item.id === selectedActivity.id ? { ...item, lawyerActivityContent: contentValue } : item
                        )
                      )
                      setSelectedActivity({ ...selectedActivity, lawyerActivityContent: contentValue })
                    }
                  }}
                  placeholder={`활동사항을 입력해 주세요.\n※ 예시 - 대한변호사협회 이사\n         - 법무부 자문위원\n         - ○○대학교 법학과 겸임교수`}
                  rows={8}
                  style={{ resize: 'none' }}
                />
              </div>
            </div>
          ) : (
            <div className={styles.emptyState}>좌측에서 카테고리를 선택하거나 추가해주세요.</div>
          )}
        </article>
      </section>
    </div>
  )
})

LawyerEditActivity.displayName = 'LawyerEditActivity'

export default LawyerEditActivity

import { useState, useImperativeHandle, forwardRef, useEffect } from 'react'
import { Input, Select, Upload, Button, Radio, message } from 'antd'
import { PlusOutlined, DeleteOutlined, MinusCircleOutlined } from '@ant-design/icons'
import { useFileUpload } from '@/hooks/useFileUpload'
import styles from './lawyerEditBasicInfo.module.scss'
import { useLawyerBasicInfo } from '@/hooks/queries/useLawyer'
import { useCategory } from '@/hooks/queries/useCategory'

const { TextArea } = Input

interface ProfileImage {
  url: string // 이미지 URL (서버에서 받은 URL)
  isExisting?: boolean // 기존 이미지인지 새로 업로드한 이미지인지 구분
  originalDisplayOrder?: number // 서버에서 받은 원래 displayOrder
  imageId?: number // 서버에서 받은 이미지 ID
}

export interface LawyerEditBasicInfoRef {
  uploadImages: () => Promise<string[]> // 업로드된 이미지 URL 배열 반환
  getFormData: () => any // 폼 데이터 반환
  getImageData: () => Array<{ imageUrl: string; displayOrder: number; imageId?: number }> // 구조화된 이미지 데이터 반환
  validateForm: () => boolean // 폼 유효성 검사
}

const LawyerEditBasicInfo = forwardRef<LawyerEditBasicInfoRef, { lawyerId: string | undefined }>((props, ref) => {
  const { lawyerId } = props
  const [profileImages, setProfileImages] = useState<(ProfileImage | null)[]>([null, null, null, null, null])
  const { uploadFile } = useFileUpload()
  const [isDataInitialized, setIsDataInitialized] = useState(false)

  const { data: lawyerBasicInfo } = useLawyerBasicInfo(Number(lawyerId))
  const { data: categoryList } = useCategory()

  // 폼 데이터 상태
  const [formData, setFormData] = useState({
    greeting: '',
    lawyerName: '',
    birthYear: undefined as number | undefined,
    birthMonth: undefined as number | undefined,
    birthDay: undefined as number | undefined,
    gender: '',
    phoneNumber: '',
    tags: '',
    lawfirmName: '',
    address: '',
    addressDetail: '',
    officePhone: '',
    categories: [] as { categoryId: number; subcategoryId: number | null }[],
  })

  // 에러 상태
  const [errors, setErrors] = useState<Record<string, string>>({})

  // 유효성 검사 함수
  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {}

    // 필수 필드 검사
    if (!formData.greeting.trim()) {
      newErrors.greeting = '인사말을 입력해주세요.'
    }

    if (!formData.lawyerName.trim()) {
      newErrors.lawyerName = '변호사 이름을 입력해주세요.'
    }

    if (!formData.birthYear) {
      newErrors.birthYear = '생년을 선택해주세요.'
    }

    if (!formData.birthMonth) {
      newErrors.birthMonth = '생월을 선택해주세요.'
    }

    if (!formData.birthDay) {
      newErrors.birthDay = '생일을 선택해주세요.'
    }

    if (!formData.gender) {
      newErrors.gender = '성별을 선택해주세요.'
    }

    if (!formData.phoneNumber.trim()) {
      newErrors.phoneNumber = '휴대폰 번호를 입력해주세요.'
    } else if (!/^010-?\d{3,4}-?\d{4}$/.test(formData.phoneNumber.replace(/-/g, ''))) {
      newErrors.phoneNumber = '올바른 휴대폰 번호 형식이 아닙니다.'
    }

    // 태그 검사 (최소 2개, 최대 4개)
    const tagArray = formData.tags
      .split(',')
      .map(tag => tag.trim())
      .filter(tag => tag.length > 0)

    if (tagArray.length < 2) {
      newErrors.tags = '최소 2개 이상의 태그를 입력해주세요.'
    } else if (tagArray.length > 4) {
      newErrors.tags = '태그는 최대 4개까지 입력 가능합니다.'
    }

    if (!formData.lawfirmName.trim()) {
      newErrors.lawfirmName = '로펌 사무실 이름을 입력해주세요.'
    }

    if (!formData.address.trim()) {
      newErrors.address = '사무실 주소를 입력해주세요.'
    }

    if (!formData.addressDetail.trim()) {
      newErrors.addressDetail = '상세주소를 입력해주세요.'
    }

    if (!formData.officePhone.trim()) {
      newErrors.officePhone = '사무실 연락처를 입력해주세요.'
    }

    // 카테고리 검사 (최소 1개 이상)
    const validCategories = formData.categories.filter(cat => cat.subcategoryId !== null)
    if (validCategories.length === 0) {
      newErrors.categories = '최소 1개 이상의 주요분야를 선택해주세요.'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  // 데이터 로드 시 폼 필드 초기화
  useEffect(() => {
    if (lawyerBasicInfo && categoryList && !isDataInitialized) {
      // subcategory ID로 해당하는 category ID 찾기
      const mappedCategories =
        lawyerBasicInfo.lawyerSubcategories?.map((sub: any) => {
          // categoryList에서 해당 subcategory를 포함하는 category 찾기
          const parentCategory = categoryList.find(cat =>
            cat.subcategories.some(s => s.subcategoryId === sub.subcategoryId)
          )

          return {
            categoryId: parentCategory?.categoryId || 0,
            subcategoryId: sub.subcategoryId || null,
          }
        }) || []

      setFormData({
        greeting: lawyerBasicInfo.lawyerDescription || '',
        lawyerName: lawyerBasicInfo.lawyerName || '',
        birthYear: lawyerBasicInfo.lawyerBirthYear || undefined,
        birthMonth: lawyerBasicInfo.lawyerBirthMonth || undefined,
        birthDay: lawyerBasicInfo.lawyerBirthDay || undefined,
        gender: lawyerBasicInfo.lawyerGender === 0 ? 'M' : 'F',
        phoneNumber: lawyerBasicInfo.lawyerPhone || '',
        tags: lawyerBasicInfo.lawyerTags?.map(tag => (typeof tag === 'string' ? tag : tag.tagName)).join(', ') || '',
        lawfirmName: lawyerBasicInfo.lawyerLawfirmName || '',
        address: lawyerBasicInfo.lawyerLawfirmAddress || '',
        addressDetail: lawyerBasicInfo.lawyerLawfirmAddressDetail || '',
        officePhone: lawyerBasicInfo.lawyerLawfirmContact || '',
        categories: mappedCategories,
      })

      // 이미지 데이터 설정
      if (lawyerBasicInfo.lawyerProfileImages && lawyerBasicInfo.lawyerProfileImages.length > 0) {
        const images: (ProfileImage | null)[] = [null, null, null, null, null]
        lawyerBasicInfo.lawyerProfileImages.forEach((img: any, index: number) => {
          if (index < 5) {
            images[index] = {
              url: img.imageUrl, // imageUrl 필드 사용
              isExisting: true,
              originalDisplayOrder: img.displayOrder, // 원래 displayOrder 저장
              imageId: img.id, // 이미지 ID 저장
            }
          }
        })
        setProfileImages(images)
      }

      setIsDataInitialized(true)
    }
  }, [lawyerBasicInfo, categoryList, isDataInitialized])

  const handleImageDelete = (index: number) => {
    const newImages = [...profileImages]
    // 삭제할 이미지 제거
    newImages.splice(index, 1)
    // 마지막에 null 추가하여 5개 유지
    newImages.push(null)
    setProfileImages(newImages)
    message.success('이미지가 삭제되었습니다.')
  }

  // 이미지 URL 배열 반환 함수 (최종 저장 시 호출)
  const uploadImages = async (): Promise<string[]> => {
    // 이미 업로드된 이미지 URL들을 그대로 반환
    return profileImages.filter(img => img !== null).map(img => img!.url)
  }

  // 구조화된 이미지 데이터 반환 함수
  const getImageData = () => {
    return profileImages
      .filter(img => img !== null)
      .map((img, index) => {
        if (img!.isExisting && img!.originalDisplayOrder) {
          // 기존 이미지는 원래 displayOrder 유지
          return {
            imageUrl: img!.url,
            displayOrder: img!.originalDisplayOrder,
            imageId: img!.imageId,
          }
        } else {
          // 새로 추가된 이미지는 현재 위치 기준으로 displayOrder 설정
          return {
            imageUrl: img!.url,
            displayOrder: index + 1,
          }
        }
      })
  }

  // 폼 데이터 반환 함수
  const getFormData = () => {
    return {
      ...formData,
      tags: formData.tags
        .split(',')
        .map(tag => tag.trim())
        .filter(tag => tag.length > 0),
    }
  }

  // 입력 핸들러
  const handleInputChange = (field: string, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }))
    // 입력 시 해당 필드의 에러 메시지 제거
    if (errors[field]) {
      setErrors(prev => {
        const newErrors = { ...prev }
        delete newErrors[field]
        return newErrors
      })
    }
  }

  // 카테고리 추가
  const handleAddCategory = () => {
    if (formData.categories.length >= 20) {
      message.warning('최대 20개까지만 추가할 수 있습니다.')
      return
    }
    setFormData(prev => ({
      ...prev,
      categories: [...prev.categories, { categoryId: 0, subcategoryId: null }],
    }))
  }

  // 카테고리 삭제
  const handleRemoveCategory = (index: number) => {
    setFormData(prev => ({
      ...prev,
      categories: prev.categories.filter((_, i) => i !== index),
    }))
  }

  // 카테고리 변경
  const handleCategoryChange = (index: number, field: 'categoryId' | 'subcategoryId', value: number | null) => {
    setFormData(prev => {
      const newCategories = [...prev.categories]
      if (field === 'categoryId') {
        newCategories[index] = { categoryId: value as number, subcategoryId: null }
      } else {
        newCategories[index] = { ...newCategories[index], subcategoryId: value }
      }
      return { ...prev, categories: newCategories }
    })
    // 카테고리 변경 시 에러 메시지 제거
    if (errors.categories) {
      setErrors(prev => {
        const newErrors = { ...prev }
        delete newErrors.categories
        return newErrors
      })
    }
  }

  // ref를 통해 부모 컴포넌트에서 호출 가능한 함수들 노출
  useImperativeHandle(ref, () => ({
    uploadImages,
    getFormData,
    getImageData,
    validateForm,
  }))

  return (
    <div className={styles['lawyer-edit-basic-info']}>
      <div className={styles.formSection}>
        {/* 프로필 사진 등록 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>프로필 사진 등록</label>
          </div>
          <div className={styles.inputCol}>
            <div className={styles.notice}>
              <p>※ 사진등록시 주의사항</p>
              <ul>
                <li>의뢰인에게 신뢰를 얻을 수 있는 사진을 등록해주세요</li>
                <li>가급적 단독 사진의 상체위주로 촬영후 등록해주시고, 전체 샷은 오히려 잘 안보일 수 있습니다.</li>
                <li>가장 최적의 사진 사이즈는 1,200 x 400이며, 최대 5장까지 등록 가능합니다.</li>
              </ul>
            </div>
            <div className={styles.imageUploadArea}>
              {profileImages.map((file, index) => {
                // 이전 슬롯이 채워졌는지 확인 (첫 번째 슬롯은 항상 활성화)
                const isPreviousFilled = index === 0 || profileImages[index - 1] !== null
                // 현재 슬롯이 활성화되어야 하는지 확인
                const isEnabled = isPreviousFilled && !file

                return (
                  <div key={index} className={styles.imageSlot}>
                    {file ? (
                      <>
                        <img src={file.url} alt={`profile-${index}`} />
                        <DeleteOutlined className={styles.deleteIcon} onClick={() => handleImageDelete(index)} />
                      </>
                    ) : (
                      <Upload
                        accept='image/jpeg,image/png,image/webp'
                        showUploadList={false}
                        disabled={!isEnabled}
                        beforeUpload={async file => {
                          try {
                            // 서버에 이미지 업로드
                            const result = await uploadFile(file, {
                              folder: `lawyer/profile/${lawyerId}`,
                              maxSize: 5,
                              allowedTypes: ['image/jpeg', 'image/png', 'image/webp'],
                            })

                            // 업로드 성공 시 URL 저장
                            const newImages = [...profileImages]
                            newImages[index] = {
                              url: result.fileUrl,
                              isExisting: false,
                            }
                            setProfileImages(newImages)
                            message.success('이미지가 업로드되었습니다.')
                          } catch (error) {
                            message.error(
                              `이미지 업로드 실패: ${error instanceof Error ? error.message : '알 수 없는 오류'}`
                            )
                          }
                          return false // 자동 업로드 방지
                        }}
                      >
                        <div className={`${styles.uploadPlaceholder} ${!isEnabled ? styles.disabled : ''}`}>
                          <PlusOutlined />
                          <div>사진등록</div>
                        </div>
                      </Upload>
                    )}
                  </div>
                )
              })}
            </div>
          </div>
        </div>

        {/* 인사말 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>인사말</label>
          </div>
          <div className={styles.inputCol}>
            <div style={{ width: '100%' }}>
              <TextArea
                rows={4}
                placeholder='의뢰인에게 보여줄 인사말을 최대 200자 이내로 입력해주세요.'
                maxLength={200}
                value={formData.greeting}
                onChange={e => handleInputChange('greeting', e.target.value)}
                style={{ resize: 'none', borderColor: errors.greeting ? '#ff4d4f' : undefined }}
                status={errors.greeting ? 'error' : undefined}
              />
              {errors.greeting && (
                <div style={{ color: '#ff4d4f', fontSize: '14px', marginTop: '4px' }}>{errors.greeting}</div>
              )}
            </div>
          </div>
        </div>

        {/* 변호사 이름 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>변호사 이름</label>
          </div>
          <div className={styles.inputCol}>
            <div style={{ width: '100%' }}>
              <Input
                placeholder='이름을 입력해주세요'
                value={formData.lawyerName}
                onChange={e => handleInputChange('lawyerName', e.target.value)}
                status={errors.lawyerName ? 'error' : undefined}
              />
              {errors.lawyerName && (
                <div style={{ color: '#ff4d4f', fontSize: '14px', marginTop: '4px' }}>{errors.lawyerName}</div>
              )}
            </div>
          </div>
        </div>

        {/* 생년월일/성별 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>생년월일/성별</label>
          </div>
          <div className={styles.inputCol}>
            <div style={{ width: '100%' }}>
              <div className={styles.flexRow}>
                <Select
                  placeholder='년도'
                  style={{ width: 100 }}
                  value={formData.birthYear}
                  onChange={value => handleInputChange('birthYear', value)}
                  status={errors.birthYear ? 'error' : undefined}
                >
                  {Array.from({ length: 50 }, (_, i) => 2024 - i).map(year => (
                    <Select.Option key={year} value={year}>
                      {year}
                    </Select.Option>
                  ))}
                </Select>
                <Select
                  placeholder='월'
                  style={{ width: 80 }}
                  value={formData.birthMonth}
                  onChange={value => handleInputChange('birthMonth', value)}
                  status={errors.birthMonth ? 'error' : undefined}
                >
                  {Array.from({ length: 12 }, (_, i) => i + 1).map(month => (
                    <Select.Option key={month} value={month}>
                      {month}
                    </Select.Option>
                  ))}
                </Select>
                <Select
                  placeholder='일'
                  style={{ width: 80 }}
                  value={formData.birthDay}
                  onChange={value => handleInputChange('birthDay', value)}
                  status={errors.birthDay ? 'error' : undefined}
                >
                  {Array.from({ length: 31 }, (_, i) => i + 1).map(day => (
                    <Select.Option key={day} value={day}>
                      {day}
                    </Select.Option>
                  ))}
                </Select>
                <Radio.Group value={formData.gender} onChange={e => handleInputChange('gender', e.target.value)}>
                  <Radio value='M'>남자</Radio>
                  <Radio value='F'>여자</Radio>
                </Radio.Group>
              </div>
              {(errors.birthYear || errors.birthMonth || errors.birthDay || errors.gender) && (
                <div style={{ color: '#ff4d4f', fontSize: '14px', marginTop: '4px' }}>
                  {errors.birthYear || errors.birthMonth || errors.birthDay || errors.gender}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* 휴대폰 번호 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>휴대폰 번호</label>
          </div>
          <div className={styles.inputCol}>
            <div style={{ width: '100%' }}>
              <Input
                placeholder='휴대폰 번호를 입력해주세요'
                value={formData.phoneNumber}
                onChange={e => handleInputChange('phoneNumber', e.target.value)}
                status={errors.phoneNumber ? 'error' : undefined}
              />
              {errors.phoneNumber && (
                <div style={{ color: '#ff4d4f', fontSize: '14px', marginTop: '4px' }}>{errors.phoneNumber}</div>
