        {/* 검찰 태그 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>
              관련 태그
              <br />
              (최소2개 / 최대 4개)
            </label>
          </div>
          <div className={styles.inputCol}>
            <div style={{ width: '100%' }}>
              <Input
                placeholder='자신있는 분야, 관련 키워드를 입력해주세요. 검색에 노출됩니다 (콤마로 구분)'
                value={formData.tags}
                onChange={e => handleInputChange('tags', e.target.value)}
                status={errors.tags ? 'error' : undefined}
              />
              {errors.tags && <div style={{ color: '#ff4d4f', fontSize: '14px', marginTop: '4px' }}>{errors.tags}</div>}
              <div className={styles.tagList} style={{ marginTop: 8 }}>
                <span className={styles.link}>2개이상의 태그를 입력해주세요. 콤마를 이용하여 구분할 수 있습니다.</span>
              </div>
            </div>
          </div>
        </div>

        {/* 로펌 사무실 이름 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>로펌 사무실 이름</label>
          </div>
          <div className={styles.inputCol}>
            <div style={{ width: '100%' }}>
              <Input
                placeholder='사무실명을 입력해주세요'
                value={formData.lawfirmName}
                onChange={e => handleInputChange('lawfirmName', e.target.value)}
                status={errors.lawfirmName ? 'error' : undefined}
              />
              {errors.lawfirmName && (
                <div style={{ color: '#ff4d4f', fontSize: '14px', marginTop: '4px' }}>{errors.lawfirmName}</div>
              )}
            </div>
          </div>
        </div>

        {/* 사무실 주소 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>사무실 주소</label>
          </div>
          <div className={styles.inputCol}>
            <div style={{ width: '100%' }}>
              <div className={styles.flexRow}>
                <Button>주소 검색하기</Button>
                <Input
                  placeholder='신주소 입력'
                  style={{ flex: 1, marginLeft: 8 }}
                  value={formData.address}
                  onChange={e => handleInputChange('address', e.target.value)}
                  status={errors.address ? 'error' : undefined}
                />
              </div>
              {errors.address && (
                <div style={{ color: '#ff4d4f', fontSize: '14px', marginTop: '4px' }}>{errors.address}</div>
              )}
              <Input
                placeholder='상세주소를 모두 입력해 주세요'
                style={{ marginTop: 8 }}
                value={formData.addressDetail}
                onChange={e => handleInputChange('addressDetail', e.target.value)}
                status={errors.addressDetail ? 'error' : undefined}
              />
              {errors.addressDetail && (
                <div style={{ color: '#ff4d4f', fontSize: '14px', marginTop: '4px' }}>{errors.addressDetail}</div>
              )}
              <div style={{ marginTop: 8 }}>
                <span className={styles.link}>주소 등록</span>
                <span className={styles.helperText}>가능합니다.</span>
              </div>
            </div>
          </div>
        </div>

        {/* 사무실 연락처 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>사무실 연락처</label>
          </div>
          <div className={styles.inputCol}>
            <div style={{ width: '100%' }}>
              <Input
                placeholder='사무실 번호를 입력해주세요'
                value={formData.officePhone}
                onChange={e => handleInputChange('officePhone', e.target.value)}
                status={errors.officePhone ? 'error' : undefined}
              />
              {errors.officePhone && (
                <div style={{ color: '#ff4d4f', fontSize: '14px', marginTop: '4px' }}>{errors.officePhone}</div>
              )}
              <div className={styles.flexRow} style={{ marginTop: 8 }}>
                <span className={styles.link}>사무실 번호 등록이</span>
                <span className={styles.helperText}>가능합니다.</span>
              </div>
            </div>
          </div>
        </div>

        {/* 주요분야 선택 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>
              주요분야 선택
              <br />
              (최소 1개 / 최대 20개)
            </label>
          </div>
          <div className={styles.inputCol}>
            <div style={{ width: '100%' }}>
              <div className={styles.categoryList}>
                {formData.categories.map((category, index) => {
                  const selectedCategory = categoryList?.find(c => c.categoryId === category.categoryId)
                  return (
                    <div key={index} className={styles.categoryItem}>
                      <Select
                        placeholder='대분류 선택'
                        value={category.categoryId || undefined}
                        onChange={value => handleCategoryChange(index, 'categoryId', value)}
                        style={{ width: 180 }}
                      >
                        {categoryList?.map(cat => (
                          <Select.Option key={cat.categoryId} value={cat.categoryId}>
                            {cat.categoryName}
                          </Select.Option>
                        ))}
                      </Select>
                      <Select
                        placeholder='소분류 선택'
                        value={category.subcategoryId || undefined}
                        onChange={value => handleCategoryChange(index, 'subcategoryId', value)}
                        disabled={!category.categoryId}
                        style={{ width: 180 }}
                      >
                        {selectedCategory?.subcategories?.map(sub => (
                          <Select.Option key={sub.subcategoryId} value={sub.subcategoryId}>
                            {sub.subcategoryName}
                          </Select.Option>
                        ))}
                      </Select>
                      <Button
                        type='text'
                        danger
                        icon={<MinusCircleOutlined />}
                        onClick={() => handleRemoveCategory(index)}
                      />
                    </div>
                  )
                })}
                {formData.categories.length < 20 && (
                  <Button type='dashed' icon={<PlusOutlined />} onClick={handleAddCategory} style={{ width: '100%' }}>
                    분야 추가
                  </Button>
                )}
              </div>
              {errors.categories && (
                <div style={{ color: '#ff4d4f', fontSize: '14px', marginTop: '4px' }}>{errors.categories}</div>
              )}
              <div style={{ marginTop: 8 }}>
                <span className={styles.link}>최소 1개 이상의 주요분야를 선택해주세요.</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
})

LawyerEditBasicInfo.displayName = 'LawyerEditBasicInfo'

export default LawyerEditBasicInfo

import { useState, forwardRef, useImperativeHandle, useEffect } from 'react'
import { Button, Input, message, Spin } from 'antd'
import { PlusOutlined, DeleteOutlined, MenuOutlined } from '@ant-design/icons'
import DraggableTable from '@/components/draggableTable/DraggableTable'
import { LawyerCareer } from '@/types/lawyerTypes'
import { useLawyerCareer } from '@/hooks/queries/useLawyer'
import styles from './lawyerEditCareer.module.scss'

const { TextArea } = Input

interface CareerItem extends LawyerCareer {
  id: string
}

export interface LawyerEditCareerRef {
  getFormData: () => LawyerCareer[]
}

interface LawyerEditCareerProps {
  lawyerId?: string
}

const LawyerEditCareer = forwardRef<LawyerEditCareerRef, LawyerEditCareerProps>(({ lawyerId }, ref) => {
  const { data: careerDataFromAPI, isLoading } = useLawyerCareer(Number(lawyerId))

  const [careerData, setCareerData] = useState<CareerItem[]>([])
  const [isInitialized, setIsInitialized] = useState(false)

  // API 데이터로 초기화
  useEffect(() => {
    if (careerDataFromAPI && !isInitialized) {
      // careerDataFromAPI가 배열인지 확인
      const dataArray = Array.isArray(careerDataFromAPI) ? careerDataFromAPI : []

      if (dataArray.length > 0) {
        const initialData = dataArray.map((item: LawyerCareer, index: number) => ({
          ...item,
          id: `api-${index}`,
        }))
        setCareerData(initialData)
      } else {
        // 데이터가 비어있으면 빈 배열 유지
        setCareerData([])
      }
      setIsInitialized(true)
    } else if (!careerDataFromAPI && !isLoading && !isInitialized) {
      // API 호출 실패 또는 데이터가 없는 경우 빈 배열
      setCareerData([])
      setIsInitialized(true)
    }
  }, [careerDataFromAPI, isLoading, isInitialized])

  const [selectedCareer, setSelectedCareer] = useState<CareerItem | null>(null)
  const [contentValue, setContentValue] = useState('')
  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null)
  const [editingCategoryName, setEditingCategoryName] = useState('')

  // 선택된 항목이 변경될 때 content 업데이트
  const handleCareerClick = (record: CareerItem) => {
    setSelectedCareer(record)
    setContentValue(record.lawyerCareerContent)
  }

  // 카테고리 이름 더블클릭 핸들러
  const handleCategoryDoubleClick = (record: CareerItem) => {
    setEditingCategoryId(record.id)
    setEditingCategoryName(record.lawyerCareerCategoryName)
  }

  // 카테고리 이름 인라인 편집 저장
  const handleCategoryNameSave = (id: string) => {
    setCareerData(prev =>
      prev.map(item => (item.id === id ? { ...item, lawyerCareerCategoryName: editingCategoryName } : item))
    )
    setEditingCategoryId(null)
    setEditingCategoryName('')

    // 선택된 항목이 편집 중인 항목이라면 업데이트
    if (selectedCareer?.id === id) {
      setSelectedCareer(prev => (prev ? { ...prev, lawyerCareerCategoryName: editingCategoryName } : null))
    }
    message.success('카테고리 이름이 변경되었습니다.')
  }

  // 카테고리 이름 인라인 편집 취소
  const handleCategoryNameCancel = () => {
    setEditingCategoryId(null)
    setEditingCategoryName('')
  }

  // 우측 테이블 컬럼
  const columns = [
    {
      title: '이력 분류',
      dataIndex: 'lawyerCareerCategoryName',
      render: (text: string, record: CareerItem) => (
        <div className={styles.categoryCell}>
          {editingCategoryId === record.id ? (
            <Input
              value={editingCategoryName}
              onChange={e => setEditingCategoryName(e.target.value)}
              onPressEnter={() => handleCategoryNameSave(record.id)}
              onBlur={() => handleCategoryNameSave(record.id)}
              onKeyDown={e => {
                if (e.key === 'Escape') {
                  handleCategoryNameCancel()
                }
              }}
              autoFocus
              size='small'
              style={{ width: '100%' }}
            />
          ) : (
            <span
              onDoubleClick={() => handleCategoryDoubleClick(record)}
              style={{ cursor: 'pointer', width: '100%', display: 'block' }}
              title='더블클릭하여 편집'
            >
              {text}
            </span>
          )}
        </div>
      ),
    },
    {
      title: '이동',
      width: 50,
      align: 'center' as const,
      render: () => <MenuOutlined style={{ cursor: 'grab', color: '#999' }} />,
    },
    {
      title: '삭제',
      width: 50,
      align: 'center' as const,
      render: (_: any, record: CareerItem) => (
        <Button
          type='text'
          size='small'
          danger
          icon={<DeleteOutlined />}
          onClick={e => {
            e.stopPropagation()
            handleDelete(record.id)
          }}
        />
      ),
    },
  ]

  // 순서 변경 핸들러
  const handleChangeOrder = (newData: CareerItem[]) => {
    const reorderedData = newData.map((item, index) => ({
      ...item,
      lawyerCareerDisplayOrder: index + 1,
    }))
    setCareerData(reorderedData)
  }

  // 카테고리 추가
  const handleAdd = () => {
    const newItem: CareerItem = {
      id: Date.now().toString(),
      lawyerCareerCategoryName: '새 카테고리',
      lawyerCareerContent: '',
      lawyerCareerDisplayOrder: careerData.length + 1,
    }
    setCareerData(prev => [...prev, newItem])
    setSelectedCareer(newItem)
    setContentValue('')
    message.success('새 카테고리가 추가되었습니다.')
  }

  // 카테고리 삭제
  const handleDelete = (id: string) => {
    setCareerData(prev => {
      const filtered = prev.filter(item => item.id !== id)
      return filtered.map((item, index) => ({
        ...item,
        lawyerCareerDisplayOrder: index + 1,
      }))
    })

    if (selectedCareer?.id === id) {
      setSelectedCareer(null)
      setContentValue('')
    }

    message.success('삭제되었습니다.')
  }

  useImperativeHandle(ref, () => ({
    getFormData: () => careerData.map(({ id, ...rest }) => rest),
  }))

  if (isLoading) {
    return (
      <div className={styles.lawyerEditCareer}>
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '400px' }}>
          <Spin size='large' />
        </div>
      </div>
    )
  }

  return (
    <div className={styles.lawyerEditCareer}>
      <section className={styles.wrapper}>
        {/* 좌측: 카테고리 리스트 */}
        <article className={styles.leftPanel}>
          <div className={styles.tableWrapper}>
            <DraggableTable
              columns={columns}
              dataSource={careerData}
              rowKey='id'
              onChangeOrder={handleChangeOrder}
              onRowClick={handleCareerClick}
            />
          </div>

          <div className={styles.addButtonWrapper}>
            <Button icon={<PlusOutlined />} onClick={handleAdd} size='middle' style={{ width: '100%' }}>
              추가
            </Button>
          </div>
        </article>

        {/* 우측: 선택된 카테고리 내용 편집 */}
        <article className={styles.rightPanel}>
          <div className={styles.panelHeader}>
            <h3 className={styles.title}>
              {selectedCareer ? <>이력분류 &gt; {selectedCareer.lawyerCareerCategoryName}</> : '이력 내용'}
            </h3>
          </div>

          {selectedCareer ? (
            <div className={styles.editorContent}>
              <div className={styles.formGroup}>
                <TextArea
                  value={contentValue}
                  onChange={e => setContentValue(e.target.value)}
                  onBlur={() => {
                    // 내용이 변경되었을 때 자동 저장
                    if (selectedCareer && contentValue !== selectedCareer.lawyerCareerContent) {
                      setCareerData(prev =>
                        prev.map(item =>
                          item.id === selectedCareer.id ? { ...item, lawyerCareerContent: contentValue } : item
                        )
                      )
                      setSelectedCareer({ ...selectedCareer, lawyerCareerContent: contentValue })
                    }
                  }}
                  placeholder={`이력사항을 연도별로 입력해 주세요.\n※ 예시 - 2021 ~ 2025 : 법률사무소 대표 변호사`}
                  rows={8}
                  style={{ resize: 'none' }}
                />
              </div>
            </div>
          ) : (
            <div className={styles.emptyState}>좌측에서 카테고리를 선택하거나 추가해주세요.</div>
          )}
        </article>
      </section>
    </div>
  )
})

LawyerEditCareer.displayName = 'LawyerEditCareer'

export default LawyerEditCareer

import React, { useState } from 'react'
import { Button, Table, TableProps } from 'antd'
import styles from './lawyerMemberList.module.scss'
import LawyerApprovalModal from '@/components/lawyerApprovalModal/LawyerApprovalModal'

// LawyerInfoListResponse의 lawyerList 항목 타입
export interface LawyerMember {
  lawyerId: number
  lawyerAccount?: string // 아이디 필드 추가 (API에 있다면)
  lawyerEmail: string
  lawyerName: string
  lawyerContact: string | null
  lawyerLawfirmName: string | null
  lawyerLawfirmContact: string
  lawyerBarExamNumber: number
  lawyerApprovalStatus: string
  lawyerLawSchoolDiplomaUrl: string | null
  lawyerCertificateUrl: string | null
  lawyerBarExamPassDate: string | null
  lawyerCreatedAt: string
}

interface LawyerMemberListProps {
  data: LawyerMember[]
  loading?: boolean
  onSort: (field: string) => void
  currentOrderBy: string
  currentSort: 'asc' | 'desc'
  onSelectionChange?: (selectedRows: LawyerMember[]) => void
}

const LawyerMemberList = ({ data, loading, onSort, currentOrderBy, currentSort, onSelectionChange }: LawyerMemberListProps) => {
  const [selectedRows, setSelectedRows] = useState<LawyerMember[]>([])
  const [modalVisible, setModalVisible] = useState(false)
  const [selectedLawyer, setSelectedLawyer] = useState<LawyerMember | null>(null)

  // Convert API sort type to Ant Design sort type
  const getSortOrder = (field: string) => {
    if (field !== currentOrderBy) return undefined
    return currentSort === 'asc' ? 'ascend' : 'descend'
  }

  const handleApprovalInfo = (lawyer: LawyerMember, e: React.MouseEvent) => {
    e.stopPropagation() // 이벤트 버블링 방지
    setSelectedLawyer(lawyer)
    setModalVisible(true)
  }

  const handleModalClose = () => {
    setModalVisible(false)
    setSelectedLawyer(null)
  }

  const handleModalSubmit = (submittedData: any) => {
    console.log('승인정보 저장:', submittedData)
    // 모달은 자체적으로 API 호출 처리
  }

  const columns: TableProps<LawyerMember>['columns'] = [
    {
      title: '아이디',
      dataIndex: 'lawyerId', // lawyerAccount가 API에 없다면 lawyerId 사용
      render: (id: number) => `lawyer${id}`, // 또는 실제 아이디 필드가 있다면 그것을 사용
      sorter: true,
      sortOrder: getSortOrder('account'),
      onHeaderCell: () => ({
        onClick: () => onSort('account'),
      }),
    },
    {
      title: '이메일 주소',
      dataIndex: 'lawyerEmail',
      sorter: true,
      sortOrder: getSortOrder('email'),
      onHeaderCell: () => ({
        onClick: () => onSort('email'),
      }),
    },
    {
      title: '변호사 이름',
      dataIndex: 'lawyerName',
      sorter: true,
      sortOrder: getSortOrder('name'),
      onHeaderCell: () => ({
        onClick: () => onSort('name'),
      }),
    },
    {
      title: '연락처',
      dataIndex: 'lawyerContact',
      render: (contact: string | null) => contact || '-',
      sorter: true,
      sortOrder: getSortOrder('phone'),
      onHeaderCell: () => ({
        onClick: () => onSort('phone'),
      }),
    },
    {
      title: '소속',
      dataIndex: 'lawyerLawfirmName',
      render: (lawfirm: string | null) => lawfirm || '-',
      sorter: true,
      sortOrder: getSortOrder('office'),
      onHeaderCell: () => ({
        onClick: () => onSort('office'),
      }),
    },
    {
      title: '출신 시험',
      dataIndex: 'lawyerBarExamNumber',
      render: (examNumber: number) => `${examNumber}회`,
      align: 'center' as const,
      sorter: true,
      sortOrder: getSortOrder('exam'),
      onHeaderCell: () => ({
        onClick: () => onSort('exam'),
      }),
    },
    {
      title: '승인여부',
      dataIndex: 'lawyerApprovalStatus',
      render: (status: string, record: LawyerMember) => {
        // 승인 상태를 한글로 변환하고 pending일 때 진행 상황 표시
        const getStatusText = (status: string, record: LawyerMember) => {
          switch (status?.toLowerCase()) {
            case 'new':
              return '신규가입'
            case 'approved':
              return '완료'
            case 'pending': {
              // pending일 때 업로드된 서류 개수 계산
              let uploadedCount = 0
              if (record.lawyerLawSchoolDiplomaUrl) uploadedCount++
              if (record.lawyerCertificateUrl) uploadedCount++
              if (record.lawyerBarExamPassDate) uploadedCount++
              return `승인대기중(${uploadedCount}/3)`
            }
            default:
              return status || '-'
          }
        }

        return (
          <div className={styles['approval-cell']}>
            <span>{getStatusText(status, record)}</span>
            <Button size='small' onClick={e => handleApprovalInfo(record, e)}>
              승인정보
            </Button>
          </div>
        )
      },
    },
  ]

  const rowSelection = {
    selectedRowKeys: selectedRows.map(row => row.lawyerId),
    onSelectAll: (selected: boolean, selectedRows: LawyerMember[]) => {
      const newSelectedRows = selected ? selectedRows : []
      setSelectedRows(newSelectedRows)
      onSelectionChange?.(newSelectedRows)
      console.log('전체 선택:', selected, selectedRows)
    },
    onSelect: (record: LawyerMember, selected: boolean) => {
      setSelectedRows(prev => {
        const newSelectedRows = selected 
          ? [...prev, record]
          : prev.filter(row => row.lawyerId !== record.lawyerId)
        onSelectionChange?.(newSelectedRows)
        return newSelectedRows
      })
      console.log('개별 선택:', record, selected)
    },
    getCheckboxProps: (record: LawyerMember) => ({
      name: record.lawyerAccount,
    }),
  }

  return (
    <div className={styles['lawyer-member-list-container']}>
      <Table<LawyerMember>
        columns={columns}
        dataSource={data}
        rowSelection={rowSelection}
        rowKey='lawyerId'
        pagination={false}
        loading={loading}
        onChange={() => {}} // 정렬은 헤더 클릭으로 처리
      />
      <LawyerApprovalModal
        open={modalVisible}
        onCancel={handleModalClose}
        onSubmit={handleModalSubmit}
        lawyerId={selectedLawyer?.lawyerId || null}
        defaultValues={{
          lawSchoolDiploma: selectedLawyer?.lawyerLawSchoolDiplomaUrl || undefined,
          lawyerLicense: selectedLawyer?.lawyerCertificateUrl || undefined,
