import React, { useState, useMemo, useEffect } from 'react'
import { Button, Spin, Alert } from 'antd'
import { DownloadOutlined } from '@ant-design/icons'
import styles from '@/pages/category/categoryManagement/categoryManagement.module.scss'
import MainCategoryTable, { MainCategoryData } from '@/container/category/mainCategoryTable/MainCategoryTable'
import SubCategoryTable, { SubCategoryData } from '@/container/category/subCategoryTable/SubCategoryTable'
import InputModal from '@/components/inputModal'
import MainCategoryEditor from '@/container/category/MainCategoryEditor'
import { useCategoryManagement } from '@/hooks/useCategoryManagement'
import { useModalHandlers } from '@/hooks/useModalHandlers'
import { useCategory } from '@/hooks/queries/useCategory'
import { useExcelExport } from '@/hooks/useExcelExport'

const CategoryManagementPage: React.FC = () => {
  // React Query로 실제 데이터 가져오기
  const { data: categoryData, isLoading, error } = useCategory()
  const [selectedCategoryId, setSelectedCategoryId] = useState<number | null>(null)
  const [pendingCategoryId, setPendingCategoryId] = useState<number | null>(null)
  const { exportCategories } = useExcelExport()

  // 서버 데이터를 컴포넌트 형식으로 변환 (categoryDisplayOrder 순서대로 정렬)
  const mainData = useMemo<MainCategoryData[] | undefined>(() => {
    if (!categoryData) return undefined

    // categoryDisplayOrder 기준으로 오름차순 정렬 (낮은 숫자가 위로)
    const sortedData = [...categoryData].sort((a, b) => {
      const orderA = a.categoryDisplayOrder ?? Number.MAX_SAFE_INTEGER
      const orderB = b.categoryDisplayOrder ?? Number.MAX_SAFE_INTEGER
      return orderA - orderB
    })

    return sortedData.map(category => ({
      key: category.categoryId.toString(),
      mainCategory: category.categoryName,
      icons: [category.categoryImageUrl || '', category.categoryClickedImageUrl || ''],
      subCategory: category.categorySubcategoryCount,
      displayOrder: category.categoryDisplayOrder, // displayOrder도 추가로 저장
    }))
  }, [categoryData])

  const subData = useMemo<SubCategoryData[] | undefined>(() => {
    if (!categoryData || !selectedCategoryId) return undefined

    const selectedCategory = categoryData.find(category => category.categoryId === selectedCategoryId)

    if (!selectedCategory) return undefined

    // subcategoryDisplayOrder 기준으로 오름차순 정렬 (낮은 숫자가 위로)
    const sortedSubcategories = [...selectedCategory.subcategories].sort((a, b) => {
      const orderA = a.subcategoryDisplayOrder ?? Number.MAX_SAFE_INTEGER
      const orderB = b.subcategoryDisplayOrder ?? Number.MAX_SAFE_INTEGER
      return orderA - orderB
    })

    return sortedSubcategories.map(sub => ({
      key: sub.subcategoryId.toString(),
      subCategory: sub.subcategoryName,
      article: sub.subcategoryBlogCaseCount || 0,
      video: sub.subcategoryVideoCaseCount || 0,
      knowledge: sub.subcategoryKnowledgeCount || 0,
      lawyer: sub.subcategoryLawyerCount || 0,
      displayOrder: sub.subcategoryDisplayOrder, // displayOrder도 추가로 저장
    }))
  }, [categoryData, selectedCategoryId])

  // 커스텀 훅으로 상태와 핸들러 분리 - 데이터 주입 방식
  const {
    mainData: processedMainData,
    subData: processedSubData,
    selectedMainCategory,
    handleMainCategoryOrderChange,
    handleMainCategoryClick: originalHandleMainCategoryClick,
    handleMainCategoryDelete,
    handleSubCategoryOrderChange,
    handleSubCategoryDelete,
    resetSelection,
    setMainCategorySelection,
  } = useCategoryManagement({
    initialMainData: mainData,
    initialSubData: selectedCategoryId ? subData : [], // selectedCategoryId가 없으면 빈 배열 전달
  })

  // 대분류 클릭 시 선택된 카테고리 ID 업데이트
  const handleMainCategoryClick = (record: MainCategoryData) => {
    const categoryId = parseInt(record.key)
    setSelectedCategoryId(categoryId)
    originalHandleMainCategoryClick(record, categoryId)
  }

  // 새로 생성된 카테고리 자동 선택 처리
  useEffect(() => {
    if (pendingCategoryId && categoryData) {
      const newCategory = categoryData.find(cat => cat.categoryId === pendingCategoryId)
      if (newCategory) {
        // 소분류 데이터 초기화
        resetSelection()

        // 카테고리 ID 설정
        setSelectedCategoryId(pendingCategoryId)

        // 선택된 대분류 이름 설정
        setMainCategorySelection(newCategory.categoryName)

        // pending 상태 초기화
        setPendingCategoryId(null)
      }
    }
  }, [categoryData, pendingCategoryId, setMainCategorySelection, resetSelection])

  const {
    isSubCategoryModalOpen,
    selectedSubCategory,
    modalMode,
    isMainCategoryEditorOpen,
    mainCategoryEditorMode,
    selectedMainCategoryData,
    handleMainCategoryAdd,
    handleMainCategoryDoubleClick,
    handleMainCategoryEditorCancel,
    handleMainCategoryEditorSubmit: originalHandleMainCategoryEditorSubmit,
    handleSubCategoryAdd,
    handleSubCategoryClick,
    handleSubCategoryDoubleClick,
    handleSubCategoryModalCancel,
    handleSubCategoryModalSubmit,
  } = useModalHandlers({ selectedCategoryId })

  // 대분류 등록/수정 시 선택된 카테고리 초기화 처리
  const handleMainCategoryEditorSubmit = async (data: any) => {
    // 대분류 추가 모드일 때 새로 생성된 카테고리 선택
    if (mainCategoryEditorMode === 'add' && data.categoryId) {
      // 새로 생성된 카테고리 ID를 pending 상태로 저장
      setPendingCategoryId(data.categoryId)
    }
    originalHandleMainCategoryEditorSubmit(data)
  }

  // 로딩 상태
  if (isLoading) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '50vh' }}>
        <Spin size='large' spinning={true} tip='데이터를 불러오는 중...'>
          <div style={{ padding: 50 }} />
        </Spin>
      </div>
    )
  }

  // 에러 상태
  if (error) {
    return (
      <div style={{ padding: '20px' }}>
        <Alert
          message='오류 발생'
          description={error instanceof Error ? error.message : '데이터를 불러오는 중 오류가 발생했습니다.'}
          type='error'
          showIcon
          action={<Button onClick={() => window.location.reload()}>다시 시도</Button>}
        />
      </div>
    )
  }

  return (
    <main className={styles.categoryManagement}>
      <header>
        <Button
          className={styles.categoryManagement__button}
          icon={<DownloadOutlined />}
          onClick={() => exportCategories(categoryData)}
        >
          전체분류 엑셀저장하기
        </Button>
      </header>
      <section className={styles.categoryManagement__wrapper}>
        <article>
          <MainCategoryTable
            data={processedMainData}
            onChangeOrder={handleMainCategoryOrderChange}
            onAdd={handleMainCategoryAdd}
            onRowClick={handleMainCategoryClick}
            onRowDoubleClick={handleMainCategoryDoubleClick}
            onDelete={handleMainCategoryDelete}
          />
        </article>
        <article>
          <SubCategoryTable
            data={processedSubData}
            onChangeOrder={handleSubCategoryOrderChange}
            onAdd={handleSubCategoryAdd}
            onRowClick={handleSubCategoryClick}
            onRowDoubleClick={handleSubCategoryDoubleClick}
            mainCategory={selectedMainCategory}
            onDelete={handleSubCategoryDelete}
          />
        </article>
      </section>

      <InputModal
        title={modalMode === 'add' ? '소분류 등록' : '분류명 변경'}
        open={isSubCategoryModalOpen}
        onCancel={handleSubCategoryModalCancel}
        onSubmit={handleSubCategoryModalSubmit}
        placeholder='소분류 이름을 입력해주세요.'
        label='소분류 이름'
        submitButtonText={modalMode === 'add' ? '등록하기' : '수정하기'}
        cancelButtonText='취소'
        defaultValue={modalMode === 'edit' ? selectedSubCategory?.subCategory : ''}
      />

      <MainCategoryEditor
        title={mainCategoryEditorMode === 'add' ? '대분류 등록' : '대분류 수정'}
        open={isMainCategoryEditorOpen}
        onCancel={handleMainCategoryEditorCancel}
        onSubmit={handleMainCategoryEditorSubmit}
        defaultValues={
          mainCategoryEditorMode === 'edit' && selectedMainCategoryData
            ? {
                id: parseInt(selectedMainCategoryData.key), // 카테고리 ID 추가
                name: selectedMainCategoryData.mainCategory,
                onImage: selectedMainCategoryData.icons[0] || '',
                offImage: selectedMainCategoryData.icons[1] || '',
              }
            : undefined
        }
      />
    </main>
  )
}

export default CategoryManagementPage

import { Button, Input, Modal, Space, Table, Upload, message, Select } from 'antd'
import { PlusOutlined } from '@ant-design/icons'
import { useState, useEffect } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useLawyerSearch } from '@/hooks/queries/useLawyer'
import { useCreateBlog } from '@/hooks/queries/useContent'
import { useFileUpload } from '@/hooks/useFileUpload'
import { useCategory } from '@/hooks/queries/useCategory'
import styles from './BlogEditor.module.scss'

const { TextArea } = Input

const BlogEditor = () => {
  const navigate = useNavigate()
  const { subCategoryId } = useParams()
  const { data: categoryList } = useCategory()
  const [selectedCategoryId, setSelectedCategoryId] = useState<number | undefined>(undefined)
  const [formData, setFormData] = useState({
    blogUrl: '',
    subcategoryId: subCategoryId || '',
    title: '',
    content: '',
    keywords: '',
    lawyer: null as any,
    thumbnail: '',
  })
  const [lawyerSearchName, setLawyerSearchName] = useState('')
  const [isLawyerModalOpen, setIsLawyerModalOpen] = useState(false)
  const [_selectedLawyerId, setSelectedLawyerId] = useState<number | null>(null)
  const [modalSearchQuery, setModalSearchQuery] = useState('')
  const [searchTrigger, setSearchTrigger] = useState({ query: '', trigger: 0 })
  const [thumbnailFileList, setThumbnailFileList] = useState<any[]>([])

  // React Query hook for lawyer search
  const { data: searchData, isLoading } = useLawyerSearch({
    searchQuery: searchTrigger.query,
    searchType: 'lawyerName',
  })

  // File upload hook for thumbnail
  const { uploadFile } = useFileUpload()

  // Create blog mutation
  const createBlogMutation = useCreateBlog({
    onSuccess: () => {
      message.success('블로그가 성공적으로 등록되었습니다.')
      navigate(-1)
    },
    onError: () => {
      message.error('블로그 등록에 실패했습니다. 다시 시도해주세요.')
    },
  })

  useEffect(() => {
    if (subCategoryId && categoryList) {
      // 서브카테고리 ID가 있으면 해당하는 카테고리 찾아서 설정
      const parentCategory = categoryList.find(cat =>
        cat.subcategories.some(sub => sub.subcategoryId === Number(subCategoryId))
      )
      if (parentCategory) {
        setSelectedCategoryId(parentCategory.categoryId)
      }
      setFormData(prev => ({
        ...prev,
        subcategoryId: subCategoryId,
      }))
    }
  }, [subCategoryId, categoryList])

  useEffect(() => {
    // If there's an existing thumbnail URL, set up the file list for display
    if (formData.thumbnail) {
      setThumbnailFileList([
        {
          uid: '-1',
          name: 'thumbnail.png',
          status: 'done',
          url: formData.thumbnail,
        },
      ])
    }
  }, [formData.thumbnail])

  const handleInputChange = (field: string, value: any) => {
    setFormData(prev => ({
      ...prev,
      [field]: value,
    }))
  }

  const handleSelectLawyer = () => {
    if (lawyerSearchName.trim()) {
      setModalSearchQuery(lawyerSearchName)
      setSearchTrigger({ query: lawyerSearchName, trigger: Date.now() })
      setIsLawyerModalOpen(true)
    }
  }

  const handleModalSearch = () => {
    if (modalSearchQuery.trim()) {
      setSearchTrigger({ query: modalSearchQuery, trigger: Date.now() })
    }
  }

  const handleLawyerSelect = (lawyerId: number) => {
    const lawyers = searchData?.lawyerSearchResults || []
    const selected = lawyers.find(lawyer => lawyer.lawyerId === lawyerId)
    if (selected) {
      setFormData(prev => ({
        ...prev,
        lawyer: selected,
      }))
      setIsLawyerModalOpen(false)
      setSelectedLawyerId(null)
      setModalSearchQuery('')
      message.success('변호사가 선택되었습니다.')
    }
  }

  const handleModalCancel = () => {
    setIsLawyerModalOpen(false)
    setSelectedLawyerId(null)
    setModalSearchQuery('')
  }

  const handleAISummary = () => {
    if (!formData.blogUrl) {
      message.warning('블로그 주소를 입력해주세요.')
      return
    }

    // Mock AI summary
    message.loading('AI 요약 중...', 1.5)

    setTimeout(() => {
      setFormData(prev => ({
        ...prev,
        title: '부동산 매매계약 시 꼭 확인해야 할 법적 체크리스트',
        content: `이 글은 부동산 매매계약을 체결할 때 반드시 확인해야 할 법적 사항들을 체계적으로 정리한 내용입니다.

1. 소유권 확인
- 등기부등본 상 소유자 확인
- 공유지분 관계 파악
- 신탁등기 여부 확인

2. 권리관계 확인
- 근저당, 전세권, 가압류 등 제한물권 확인
- 임차인 현황 및 대항력 확인
- 유치권 존재 여부 파악

3. 공법상 제한 확인
- 토지이용계획확인서 검토
- 건축물대장 확인
- 개발행위허가 제한 여부

4. 계약서 작성 시 주의사항
- 특약사항 명확히 기재
- 하자담보책임 기간 설정
- 위약금 및 손해배상 조항 검토

5. 잔금 지급 시 확인사항
- 등기 이전 절차 확인
- 세금 정산 내역 검토
- 명도 시기 및 방법 확정`,
        keywords: '부동산매매, 등기부등본, 근저당권, 전세권, 가압류, 계약서작성, 특약사항, 하자담보책임',
      }))
      message.success('AI 요약이 완료되었습니다.')
    }, 1500)
  }

  const handleThumbnailUpload = async (options: any) => {
    const { file, onSuccess, onError } = options
    try {
      const result = await uploadFile(file, { folder: 'thumbnail/blog' })
      if (result?.fileUrl) {
        setFormData(prev => ({
          ...prev,
          thumbnail: result.fileUrl,
        }))
        onSuccess(result.fileUrl)
        message.success('썸네일 이미지가 업로드되었습니다.')
      }
    } catch (error) {
      onError(error)
      message.error('썸네일 업로드에 실패했습니다.')
    }
  }

  const handleThumbnailChange = (info: any) => {
    setThumbnailFileList(info.fileList)
  }

  const handleThumbnailRemove = () => {
    setFormData(prev => ({
      ...prev,
      thumbnail: '',
    }))
    setThumbnailFileList([])
  }

  const handleSave = () => {
    // Validation
    if (!formData.blogUrl) {
      message.warning('블로그 주소를 입력해주세요.')
      return
    }
    if (!formData.title) {
      message.warning('제목을 입력해주세요.')
      return
    }
    if (!formData.content) {
      message.warning('AI요약 내용을 입력해주세요.')
      return
    }
    if (!formData.lawyer) {
      message.warning('변호사를 선택해주세요.')
      return
    }
    if (!formData.subcategoryId) {
      message.warning('카테고리를 선택해주세요.')
      return
    }

    // Prepare tags array from keywords string
    const tagsArray = formData.keywords
      ? formData.keywords
          .split(',')
          .map(tag => tag.trim())
          .filter(tag => tag.length > 0)
      : []

    // Create blog request
    const createBlogRequest = {
      blogCaseId: Date.now(), // Temporary ID, should be generated by backend
      blogCaseTitle: formData.title,
      blogCaseSummaryContent: formData.content,
      blogCaseSource: formData.blogUrl,
      blogCaseTags: tagsArray,
      blogCaseLawyerId: formData.lawyer.lawyerId,
      subcategoryId: Number(formData.subcategoryId),
      blogCaseThumbnail: formData.thumbnail || '',
    }

    createBlogMutation.mutate(createBlogRequest)
  }

  const handleCancel = () => {
    navigate(-1)
  }

  // Check if all required fields are filled
  const isFormValid = () => {
    return !!(
      formData.blogUrl &&
      formData.title &&
      formData.content &&
      formData.thumbnail &&
      formData.lawyer &&
      formData.subcategoryId
    )
  }

  return (
    <div className={styles.blogEditor}>
      <h1 className={styles.blogEditor__title}>
        <span>♦</span> 법률정보 글 입력
      </h1>
      <section className={styles.blogEditor__form}>
        {/* 카테고리 선택 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>카테고리 선택</label>
          </div>
          <div className={styles.inputCol}>
            <div style={{ display: 'flex', gap: '8px', width: '100%' }}>
              <Select
                placeholder='대분류 선택'
                value={selectedCategoryId}
                onChange={value => {
                  setSelectedCategoryId(value)
                  // 대분류 변경 시 서브카테고리 초기화
                  setFormData(prev => ({ ...prev, subcategoryId: '' }))
                }}
                style={{ width: 200 }}
                size='large'
              >
                {categoryList?.map(cat => (
                  <Select.Option key={cat.categoryId} value={cat.categoryId}>
                    {cat.categoryName}
                  </Select.Option>
                ))}
              </Select>
              <Select
                placeholder='소분류 선택'
                value={formData.subcategoryId ? Number(formData.subcategoryId) : undefined}
                onChange={value => {
                  handleInputChange('subcategoryId', value?.toString() || '')
                }}
                disabled={!selectedCategoryId}
                style={{ width: 200 }}
                size='large'
              >
                {categoryList
                  ?.find(cat => cat.categoryId === selectedCategoryId)
                  ?.subcategories?.map(sub => (
                    <Select.Option key={sub.subcategoryId} value={sub.subcategoryId}>
                      {sub.subcategoryName}
                    </Select.Option>
                  ))}
              </Select>
            </div>
          </div>
        </div>

        {/* 블로그 주소 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>블로그 주소</label>
          </div>
          <div className={styles.inputCol}>
            <Input
              placeholder='네이버 블로그 주소를 입력해주세요.'
              size='large'
              value={formData.blogUrl}
              onChange={e => handleInputChange('blogUrl', e.target.value)}
            />
          </div>
        </div>

        {/* AI요약하기 버튼 (별도 섹션) */}
        <div className={styles.aiSummarySection}>
          <Button
            type='primary'
            size='large'
            className={styles.aiButton}
            onClick={handleAISummary}
            disabled={!formData.blogUrl}
          >
            AI요약하기
          </Button>
        </div>

        {/* 썸네일 이미지 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>썸네일 이미지</label>
          </div>
          <div className={styles.inputCol}>
            <Upload
              listType='picture-card'
              fileList={thumbnailFileList}
              customRequest={handleThumbnailUpload}
              onChange={handleThumbnailChange}
              onRemove={handleThumbnailRemove}
              maxCount={1}
              accept='image/*'
            >
              {thumbnailFileList.length === 0 && (
                <div>
                  <PlusOutlined />
                  <div style={{ marginTop: 8 }}>이미지 업로드</div>
                </div>
              )}
            </Upload>
            <div style={{ marginTop: 8, marginLeft: 10, color: '#8c8c8c', fontSize: 12 }}>
              * 권장 사이즈: 800 x 450px (16:9 비율)
            </div>
          </div>
        </div>

        {/* 제목 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>제목</label>
          </div>
          <div className={styles.inputCol}>
            <Input
              placeholder='제목을 입력해주세요.'
              size='large'
              value={formData.title}
              onChange={e => handleInputChange('title', e.target.value)}
            />
          </div>
        </div>

        {/* AI요약 내용 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>AI요약 내용</label>
          </div>
          <div className={styles.inputCol}>
            <TextArea
              placeholder='블로그 주소를 입력후, AI요약이 완료되면 내용이 입력되이 됩니다.&#10;변경할 사항이 있다면 직접 변경해 주세요.'
              rows={10}
              value={formData.content}
              onChange={e => handleInputChange('content', e.target.value)}
              style={{ resize: 'none' }}
            />
          </div>
        </div>

        {/* 키워드/태그(콤마로 구분) */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>키워드/태그(콤마로 구분)</label>
          </div>
          <div className={styles.inputCol}>
            <Input
              placeholder='AI요약과 동시에 키워드/태그가 입력되어 집니다. 최대 10개까지 등록 가능합니다.'
              size='large'
              value={formData.keywords}
              onChange={e => handleInputChange('keywords', e.target.value)}
            />
          </div>
        </div>

        {/* 변호사 선택 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>변호사 선택</label>
          </div>
          <div className={styles.inputCol}>
            <div className={styles.lawyerSection}>
              <div className={styles.lawyerSearchRow}>
                <Input
                  placeholder='변호사 이름'
                  size='large'
                  value={lawyerSearchName}
                  onChange={e => setLawyerSearchName(e.target.value)}
                  onPressEnter={handleSelectLawyer}
                  className={styles.lawyerInput}
                />
                <Button size='large' onClick={handleSelectLawyer} disabled={!lawyerSearchName.trim()}>
                  검색하기
                </Button>
              </div>

              {formData.lawyer && (
                <div className={styles.lawyerInfo}>
                  <div className={styles.lawyerCard}>
                    <img
                      src={formData.lawyer.lawyerProfileImage || '/default-profile.png'}
                      alt={formData.lawyer.lawyerName}
                      className={styles.lawyerImage}
                    />
                    <div className={styles.lawyerDetails}>
                      <ul>
                        <li>로펌 사무실 : {formData.lawyer.lawyerLawfirmName || '-'}</li>
                        <li>변호사 이름 : {formData.lawyer.lawyerName}</li>
                        <li>
                          생년월일/성별 : {formData.lawyer.birthDate || '-'} / {formData.lawyer.gender || '-'}
                        </li>
                        <li>휴대폰 번호 : {formData.lawyer.phone || '-'}</li>
                        <li>주요분야 : {formData.lawyer.specialties || '-'}</li>
                      </ul>
                      <Button type='primary' size='large' className={styles.confirmButton}>
                        변호사정보 바로가기
                      </Button>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* 액션 버튼 */}
      <div className={styles.blogEditor__actions}>
        <Space>
          <Button size='large' onClick={handleCancel}>
            취소
          </Button>
          <Button
            type='primary'
            size='large'
            onClick={handleSave}
            loading={createBlogMutation.isPending}
            disabled={!isFormValid()}
          >
            저장
          </Button>
        </Space>
      </div>

      {/* 변호사 검색 모달 */}
      <Modal title='변호사 이름 검색' open={isLawyerModalOpen} onCancel={handleModalCancel} width={900} footer={null}>
        <div style={{ marginBottom: 16 }}>
          <Space.Compact style={{ width: '100%' }}>
            <Input
              placeholder='변호사 이름을 검색해주세요'
              value={modalSearchQuery}
              onChange={e => setModalSearchQuery(e.target.value)}
              onPressEnter={handleModalSearch}
              size='large'
              style={{ flex: 1 }}
            />
            <Button type='primary' size='large' onClick={handleModalSearch} style={{ width: 100 }}>
              검색
            </Button>
          </Space.Compact>
        </div>

        <Table
          dataSource={searchData?.lawyerSearchResults || []}
          rowKey='lawyerId'
          loading={isLoading}
          pagination={false}
          locale={{ emptyText: modalSearchQuery ? '검색 결과가 없습니다.' : '변호사 이름을 검색해주세요.' }}
          columns={[
            {
              title: '변호사 사진',
              dataIndex: 'lawyerProfileImage',
              key: 'lawyerProfileImage',
              width: 100,
              render: (image: string | null, record: any) => (
                <div
                  style={{
                    width: 60,
                    height: 60,
                    backgroundColor: '#f0f0f0',
                    borderRadius: '50%',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: 24,
                    color: '#999',
                  }}
                >
                  {image ? (
                    <img
                      src={image}
                      alt={record.lawyerName}
                      style={{ width: '100%', height: '100%', borderRadius: '50%', objectFit: 'cover' }}
                    />
                  ) : (
                    <span>👤</span>
                  )}
                </div>
              ),
            },
            {
              title: '변호사명',
              dataIndex: 'lawyerName',
              key: 'lawyerName',
              width: 150,
            },
            {
              title: '소속',
              dataIndex: 'lawyerLawfirmName',
              key: 'lawyerLawfirmName',
              render: (value: string | null) => value || '-',
            },
            {
              title: '가입일자',
              dataIndex: 'lawyerCreatedAt',
              key: 'lawyerCreatedAt',
              width: 120,
              render: (value: string) => {
                if (!value) return '-'
                const date = new Date(value)
                return `${date.getFullYear()}.${String(date.getMonth() + 1).padStart(2, '0')}.${String(
                  date.getDate()
                ).padStart(2, '0')}`
              },
            },
            {
              title: '선택',
              key: 'action',
              width: 100,
              render: (_: any, record: any) => (
                <Button
                  type='primary'
                  onClick={() => handleLawyerSelect(record.lawyerId)}
                  style={{ backgroundColor: '#52c41a', borderColor: '#52c41a' }}
                >
                  선택하기
                </Button>
              ),
            },
          ]}
        />
      </Modal>
    </div>
  )
}

export default BlogEditor

import { Button, Input, Modal, Space, Table, message, Select } from 'antd'
import { useState, useEffect } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useLawyerSearch } from '@/hooks/queries/useLawyer'
import { useCreateVideo, useGetVideoChannelInfo } from '@/hooks/queries/useContent'
import { useVideoAiSummary } from '@/hooks/queries/useAiSummary'
import { useCategory } from '@/hooks/queries/useCategory'
import styles from './VideoEditor.module.scss'
import { GetVideoChannelInfoResponse } from '@/types/videoTypes'

const VideoEditor = () => {
  const navigate = useNavigate()
  const { subCategoryId } = useParams()
  const { data: categoryList } = useCategory()
  const [selectedCategoryId, setSelectedCategoryId] = useState<number | undefined>(undefined)
  const [formData, setFormData] = useState({
    subcategoryId: subCategoryId ? Number(subCategoryId) : 0,
    videoCaseTitle: '',
    videoCaseSummaryContent: '',
    videoCaseSource: '',
    videoCaseThumbnail: '',
    videoCaseChannelDescription: '',
    videoCaseChannelThumbnail: '',
    videoCaseHandleName: '',
    videoCaseChannelName: '',
    videoCaseTags: [] as string[],
    videoCaseLawyerId: 0,
  })
  const [lawyerSearchName, setLawyerSearchName] = useState('')
  const [isLawyerModalOpen, setIsLawyerModalOpen] = useState(false)
  const [_selectedLawyerId, setSelectedLawyerId] = useState<number | null>(null)
  const [modalSearchQuery, setModalSearchQuery] = useState('')
  const [searchTrigger, setSearchTrigger] = useState({ query: '', trigger: 0 })
  const [isChannelInfoFetched, setIsChannelInfoFetched] = useState(false)
  const [subscriberCount, setSubscriberCount] = useState(0)
  const [shouldFetchSummary, setShouldFetchSummary] = useState(false)
  const [summaryUrl, setSummaryUrl] = useState('')

  const { mutate: channelInfo } = useGetVideoChannelInfo({
    onSuccess: (data: GetVideoChannelInfoResponse) => {
      setFormData(prev => ({
        ...prev,
        videoCaseChannelName: data.channelName,
        videoCaseHandleName: data.handleName,
        videoCaseChannelDescription: data.channelDescription,
        videoCaseChannelThumbnail: data.channelThumbnail,
      }))
      setSubscriberCount(data.subscriberCount)
      setIsChannelInfoFetched(true)
    },
    onError: () => {
      message.error('채널 정보 불러오기에 실패했습니다. 다시 시도해주세요.')
    },
  })

  // AI Summary hook
  const {
    data: summaryData,
    isLoading: isSummaryLoading,
    refetch: refetchSummary,
  } = useVideoAiSummary(
    { url: summaryUrl },
    {
      enabled: false, // 수동으로 refetch할 것이므로 기본적으로 비활성화
    }
  )

  // AI 요약 데이터 받아온 후 처리
  useEffect(() => {
    if (summaryData && shouldFetchSummary) {
      setFormData(prev => ({
        ...prev,
        videoCaseSummaryContent: summaryData.text,
        videoCaseTags: summaryData.tags || [],
      }))
      message.success('AI 요약이 완료되었습니다.')
      setShouldFetchSummary(false)
    }
  }, [summaryData, shouldFetchSummary])

  // React Query hook for lawyer search
  const { data: searchData, isLoading } = useLawyerSearch({
    searchQuery: searchTrigger.query,
    searchType: 'lawyerName',
  })

  // Create video mutation
  const createVideoMutation = useCreateVideo({
    onSuccess: () => {
      message.success('영상정보가 성공적으로 등록되었습니다.')
      navigate(-1)
    },
    onError: () => {
      message.error('영상정보 등록에 실패했습니다. 다시 시도해주세요.')
    },
  })

  useEffect(() => {
    if (subCategoryId && categoryList) {
      // 서브카테고리 ID가 있으면 해당하는 카테고리 찾아서 설정
      const parentCategory = categoryList.find(cat =>
        cat.subcategories.some(sub => sub.subcategoryId === Number(subCategoryId))
      )
      if (parentCategory) {
        setSelectedCategoryId(parentCategory.categoryId)
      }
      setFormData(prev => ({
        ...prev,
        subcategoryId: Number(subCategoryId),
      }))
    }
  }, [subCategoryId, categoryList])

  const handleInputChange = (field: string, value: any) => {
    setFormData(prev => ({
      ...prev,
      [field]: value,
    }))
  }

  const handleSelectLawyer = () => {
    if (lawyerSearchName.trim()) {
      setModalSearchQuery(lawyerSearchName)
      setSearchTrigger({ query: lawyerSearchName, trigger: Date.now() })
      setIsLawyerModalOpen(true)
    }
  }

  const handleModalSearch = () => {
    if (modalSearchQuery.trim()) {
      setSearchTrigger({ query: modalSearchQuery, trigger: Date.now() })
    }
  }

  const handleLawyerSelect = (lawyerId: number) => {
    const lawyers = searchData?.lawyerSearchResults || []
    const selected = lawyers.find(lawyer => lawyer.lawyerId === lawyerId)
    if (selected) {
      setFormData(prev => ({
        ...prev,
        videoCaseLawyerId: selected.lawyerId,
        selectedLawyer: selected, // 표시용으로 변호사 정보 저장
      }))
      setIsLawyerModalOpen(false)
      setSelectedLawyerId(null)
      setModalSearchQuery('')
      message.success('변호사가 선택되었습니다.')
    }
  }

  const handleModalCancel = () => {
    setIsLawyerModalOpen(false)
    setSelectedLawyerId(null)
    setModalSearchQuery('')
  }

  const handleFetchChannelInfo = () => {
    if (!formData.videoCaseSource) {
      message.warning('유튜브 채널 정보를 입력해주세요.')
      return
    }

    channelInfo({ channelUrl: formData.videoCaseSource })
  }

  const handleAiSummary = async () => {
    if (!formData.videoCaseSource) {
      message.warning('먼저 유튜브 URL을 입력해주세요.')
      return
    }

    setShouldFetchSummary(true)
    setSummaryUrl(formData.videoCaseSource)

    // URL이 설정된 후 refetch 실행
    setTimeout(() => {
      refetchSummary()
    }, 100)
  }

  const handleSave = () => {
    // Validation
    if (!formData.videoCaseSource) {
      message.warning('유튜브 채널 정보를 입력해주세요.')
      return
    }
    if (!formData.videoCaseTitle) {
      message.warning('영상 제목을 입력해주세요.')
      return
    }
    if (!formData.videoCaseSummaryContent) {
      message.warning('유튜브 영상정보를 입력해주세요.')
      return
    }
    if (!formData.videoCaseLawyerId) {
      message.warning('변호사를 선택해주세요.')
      return
    }
    if (!formData.subcategoryId) {
      message.warning('카테고리를 선택해주세요.')
      return
    }

    // formData를 그대로 전달
    createVideoMutation.mutate(formData)
  }

  const handleCancel = () => {
    navigate(-1)
  }

  // Check if all required fields are filled
  const isFormValid = () => {
    return !!(
      (
        formData.videoCaseSource &&
        formData.videoCaseTitle &&
        formData.videoCaseSummaryContent &&
        formData.videoCaseLawyerId &&
        formData.subcategoryId &&
        isChannelInfoFetched
      ) // YouTube channel info must be fetched
    )
  }

  return (
    <div className={styles.videoEditor}>
      <h1 className={styles.videoEditor__title}>
        <span>♦</span> 영상정보입력
      </h1>
      <section className={styles.videoEditor__form}>
        {/* 카테고리 선택 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>카테고리 선택</label>
          </div>
          <div className={styles.inputCol}>
            <div style={{ display: 'flex', gap: '8px', width: '100%' }}>
              <Select
                placeholder='대분류 선택'
                value={selectedCategoryId}
                onChange={value => {
                  setSelectedCategoryId(value)
                  // 대분류 변경 시 서브카테고리 초기화
                  setFormData(prev => ({ ...prev, subcategoryId: 0 }))
                }}
                style={{ width: 200 }}
                size='large'
              >
                {categoryList?.map(cat => (
                  <Select.Option key={cat.categoryId} value={cat.categoryId}>
                    {cat.categoryName}
                  </Select.Option>
                ))}
              </Select>
              <Select
                placeholder='소분류 선택'
                value={formData.subcategoryId || undefined}
                onChange={value => {
                  handleInputChange('subcategoryId', value || 0)
                }}
                disabled={!selectedCategoryId}
                style={{ width: 200 }}
                size='large'
              >
                {categoryList
                  ?.find(cat => cat.categoryId === selectedCategoryId)
                  ?.subcategories?.map(sub => (
                    <Select.Option key={sub.subcategoryId} value={sub.subcategoryId}>
                      {sub.subcategoryName}
                    </Select.Option>
                  ))}
              </Select>
            </div>
          </div>
        </div>

        {/* 유튜브 채널 정보 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>유튜브 채널 정보</label>
          </div>
          <div className={styles.inputCol}>
            <Input
              placeholder='유튜브 채널 홈화면의 경로를 입력해주세요.'
              size='large'
              value={formData.videoCaseSource}
              onChange={e => handleInputChange('videoCaseSource', e.target.value)}
            />
          </div>
        </div>

        {/* 유튜브 채널정보 불러오기 버튼 (별도 섹션) */}
        <div className={styles.fetchButtonSection}>
          <Button
            type='primary'
            size='large'
            className={styles.fetchButton}
            onClick={handleFetchChannelInfo}
            disabled={!formData.videoCaseSource}
          >
            유튜브채널정보불러오기
          </Button>
          {formData.videoCaseChannelName && (
            <div className={styles.channelInfoList}>
              <ul>
                <li>채널 명: {formData.videoCaseChannelName}</li>
                <li>구독자 수: {subscriberCount}명</li>
                <li>핸들 명: @{formData.videoCaseHandleName}</li>
                <li>채널 설명: {formData.videoCaseChannelDescription}</li>
              </ul>
            </div>
          )}
        </div>

        {/* 유튜브 영상정보 (URL) */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>유튜브 영상정보</label>
          </div>
          <div className={styles.inputCol} style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <Input
              placeholder='유튜브 URL을 입력해주세요.'
              size='large'
              value={formData.videoCaseSource}
              onChange={e => handleInputChange('videoCaseSource', e.target.value)}
            />
            <Button
              type='primary'
              size='large'
              onClick={handleAiSummary}
              loading={isSummaryLoading}
              disabled={!formData.videoCaseSource}
            >
              AI요약하기
            </Button>
          </div>
        </div>

        {/* 영상 제목 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>영상 제목</label>
          </div>
          <div className={styles.inputCol}>
            <Input
              placeholder='제목을 입력해주세요.'
              size='large'
              value={formData.videoCaseTitle}
              onChange={e => handleInputChange('videoCaseTitle', e.target.value)}
            />
          </div>
        </div>

        {/* 영상 내용 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>영상 내용</label>
          </div>
          <div className={styles.inputCol}>
            <Input.TextArea
              placeholder='영상 내용을 입력해주세요.'
              rows={4}
              value={formData.videoCaseSummaryContent}
              onChange={e => handleInputChange('videoCaseSummaryContent', e.target.value)}
            />
          </div>
        </div>

        {/* 키워드/태그(콤마로 구분) */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>키워드/태그(콤마로 구분)</label>
          </div>
          <div className={styles.inputCol}>
            <Input
              placeholder='키워드/태그를 입력해주세요. 최대 10개까지 등록 가능합니다.'
              size='large'
              value={formData.videoCaseTags.join(', ')}
              onChange={e => {
                const tags = e.target.value
                  .split(',')
                  .map(tag => tag.trim())
                  .filter(tag => tag.length > 0)
                handleInputChange('videoCaseTags', tags)
              }}
            />
          </div>
        </div>

        {/* 변호사 선택 */}
        <div className={styles.formRow}>
          <div className={styles.labelCol}>
            <label className={styles.label}>변호사 선택</label>
          </div>
          <div className={styles.inputCol}>
            <div className={styles.lawyerSection}>
              <div className={styles.lawyerSearchRow}>
                <Input
                  placeholder='변호사 이름'
                  size='large'
                  value={lawyerSearchName}
                  onChange={e => setLawyerSearchName(e.target.value)}
                  onPressEnter={handleSelectLawyer}
                  className={styles.lawyerInput}
                />
                <Button size='large' onClick={handleSelectLawyer} disabled={!lawyerSearchName.trim()}>
                  검색하기
                </Button>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* 액션 버튼 */}
      <div className={styles.videoEditor__actions}>
        <Space>
          <Button size='large' onClick={handleCancel}>
            취소
          </Button>
          <Button
            type='primary'
            size='large'
            onClick={handleSave}
            loading={createVideoMutation.isPending}
            disabled={!isFormValid()}
          >
            저장
          </Button>
        </Space>
      </div>

      {/* 변호사 검색 모달 */}
      <Modal title='변호사 이름 검색' open={isLawyerModalOpen} onCancel={handleModalCancel} width={900} footer={null}>
        <div style={{ marginBottom: 16 }}>
          <Space.Compact style={{ width: '100%' }}>
            <Input
              placeholder='변호사 이름을 검색해주세요'
              value={modalSearchQuery}
              onChange={e => setModalSearchQuery(e.target.value)}
              onPressEnter={handleModalSearch}
              size='large'
              style={{ flex: 1 }}
            />
            <Button type='primary' size='large' onClick={handleModalSearch} style={{ width: 100 }}>
              검색
            </Button>
          </Space.Compact>
        </div>

        <Table
          dataSource={searchData?.lawyerSearchResults || []}
          rowKey='lawyerId'
          loading={isLoading}
          pagination={false}
          locale={{ emptyText: modalSearchQuery ? '검색 결과가 없습니다.' : '변호사 이름을 검색해주세요.' }}
          columns={[
            {
              title: '변호사 사진',
              dataIndex: 'lawyerProfileImage',
              key: 'lawyerProfileImage',
              width: 100,
              render: (image: string | null, record: any) => (
                <div
                  style={{
                    width: 60,
                    height: 60,
                    backgroundColor: '#f0f0f0',
                    borderRadius: '50%',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: 24,
                    color: '#999',
                  }}
                >
                  {image ? (
                    <img
                      src={image}
                      alt={record.lawyerName}
                      style={{ width: '100%', height: '100%', borderRadius: '50%', objectFit: 'cover' }}
                    />
                  ) : (
                    <span>👤</span>
                  )}
                </div>
              ),
            },
            {
              title: '변호사명',
              dataIndex: 'lawyerName',
              key: 'lawyerName',
              width: 150,
            },
            {
              title: '소속',
              dataIndex: 'lawyerLawfirmName',
              key: 'lawyerLawfirmName',
              render: (value: string | null) => value || '-',
            },
            {
              title: '가입일자',
              dataIndex: 'lawyerCreatedAt',
              key: 'lawyerCreatedAt',
              width: 120,
              render: (value: string) => {
                if (!value) return '-'
                const date = new Date(value)
                return `${date.getFullYear()}.${String(date.getMonth() + 1).padStart(2, '0')}.${String(
                  date.getDate()
                ).padStart(2, '0')}`
              },
            },
            {
              title: '선택',
              key: 'action',
              width: 100,
              render: (_: any, record: any) => (
                <Button
                  type='primary'
                  onClick={() => handleLawyerSelect(record.lawyerId)}
                  style={{ backgroundColor: '#52c41a', borderColor: '#52c41a' }}
                >
                  선택하기
                </Button>
              ),
            },
          ]}
        />
      </Modal>
    </div>
  )
}

export default VideoEditor

import { useState, useRef } from 'react'
import { Button, Tabs, message } from 'antd'
import { useLocation, useNavigate, useParams } from 'react-router-dom'
import styles from './lawyerEdit.module.scss'
import LawyerEditBasicInfo, { LawyerEditBasicInfoRef } from '@/container/lawyer/lawyerEditBasicInfo/LawyerEditBasicInfo'
import LawyerEditActivity, { LawyerEditActivityRef } from '@/container/lawyer/lawyerEditActivity/LawyerEditActivity'
import LawyerEditCareer, { LawyerEditCareerRef } from '@/container/lawyer/lawyerEditCareer/LawyerEditCareer'
import LawyerEditAchievements from '@/container/lawyer/lawyerEditAchievements/LawyerEditAchievements'
import { useLawyerBasicInfoUpdate, useLawyerCareerUpdate, useLawyerActivityUpdate } from '@/hooks/queries/useLawyer'
import { LawyerUpdateRequest } from '@/types/lawyerTypes'

const LawyerEditPage = () => {
  const navigate = useNavigate()
  const { lawyerId } = useParams<{ lawyerId: string }>()
  const { state } = useLocation()
  const [activeTab, setActiveTab] = useState('basic')
  const [isSaving, setIsSaving] = useState(false)

  // 각 탭 컴포넌트의 ref
  const basicInfoRef = useRef<LawyerEditBasicInfoRef>(null)
  const achievementsRef = useRef<any>(null)
  const careerRef = useRef<LawyerEditCareerRef>(null)
  const activityRef = useRef<LawyerEditActivityRef>(null)

  // 기본정보 업데이트 훅
  const updateBasicInfoMutation = useLawyerBasicInfoUpdate(
    Number(lawyerId),
    () => {
      message.success('기본정보가 저장되었습니다.')
      setIsSaving(false)
    },
    () => {
      message.error('저장 중 오류가 발생했습니다.')
      setIsSaving(false)
    }
  )

  // 이력사항 업데이트 훅
  const updateCareerMutation = useLawyerCareerUpdate(
    Number(lawyerId),
    () => {
      message.success('이력 사항이 저장되었습니다.')
      setIsSaving(false)
    },
    () => {
      message.error('이력 사항 저장 중 오류가 발생했습니다.')
      setIsSaving(false)
    }
  )

  // 활동사항 업데이트 훅
  const updateActivityMutation = useLawyerActivityUpdate(
    Number(lawyerId),
    () => {
      message.success('활동 사항이 저장되었습니다.')
      setIsSaving(false)
    },
    () => {
      message.error('활동 사항 저장 중 오류가 발생했습니다.')
      setIsSaving(false)
    }
  )

  const items = [
    {
      label: '변호사 기본정보',
      key: 'basic',
      children: <LawyerEditBasicInfo ref={basicInfoRef} lawyerId={lawyerId} />,
    },
    { label: '업적 관리', key: 'achievements', children: <LawyerEditAchievements /> },
    { label: '이력 사항', key: 'career', children: <LawyerEditCareer ref={careerRef} lawyerId={lawyerId} /> },
    { label: '활동 사항', key: 'activity', children: <LawyerEditActivity ref={activityRef} lawyerId={lawyerId} /> },
  ]

  const handleCancel = () => {
    navigate(-1)
  }

  const handleSave = async () => {
    // mutation이 진행 중이거나 이미 저장 중인 경우 차단
    if (
      isSaving ||
      updateBasicInfoMutation.isPending ||
      updateCareerMutation.isPending ||
      updateActivityMutation.isPending
    ) {
      return
    }

    setIsSaving(true)

    try {
      switch (activeTab) {
        case 'basic':
          if (basicInfoRef.current) {
            // 유효성 검사 수행
            const isValid = basicInfoRef.current.validateForm()
            if (!isValid) {
              message.error('필수 입력 항목을 모두 입력해주세요.')
              setIsSaving(false)
              return
            }

            const formData = basicInfoRef.current.getFormData()
            const imageData = basicInfoRef.current.getImageData()

            // LawyerUpdateRequest 타입에 맞춰 데이터 구성
            const requestData: LawyerUpdateRequest = {
              // LawyerBasicInfo에서 상속받은 필드들 (Omit으로 제외된 필드 제외)
              lawyerDescription: formData.greeting || '',
              lawyerName: formData.lawyerName || '',
              lawyerBirthYear: formData.birthYear || 0,
              lawyerBirthMonth: formData.birthMonth || 0,
              lawyerBirthDay: formData.birthDay || 0,
              lawyerGender: formData.gender === 'M' ? 0 : 1,
              lawyerPhone: formData.phoneNumber || '',
              lawyerLawfirmName: formData.lawfirmName || '',
              lawyerLawfirmAddress: formData.address || '',
              lawyerLawfirmAddressDetail: formData.addressDetail || '',
              lawyerLawfirmContact: formData.officePhone || '',
              lawyerSubcategories: formData.categories
                .filter((cat: any) => cat.subcategoryId)
                .map((cat: any) => ({
                  subcategoryId: cat.subcategoryId,
                  subcategoryName: '', // API에서 필요시 채워질 값
                })),

              // LawyerUpdateRequest 고유 필드들 (재정의된 필드)
              lawyerTags: formData.tags || [], // 문자열 배열
              lawyerProfileImages: imageData, // 구조화된 이미지 데이터 사용
            }

            // API 호출
            updateBasicInfoMutation.mutate(requestData)
          }
          break

        case 'achievements':
          if (achievementsRef.current) {
            // TODO: achievements 데이터 가져오기 및 API 호출
            message.success('업적 정보가 저장되었습니다.')
            setIsSaving(false)
          }
          break

        case 'career':
          if (careerRef.current) {
            const careerData = careerRef.current.getFormData()

            // 데이터 유효성 검사
            const hasEmptyCategory = careerData.some(
              item => !item.lawyerCareerCategoryName || item.lawyerCareerCategoryName.trim() === ''
            )
            if (hasEmptyCategory) {
              message.warning('이력 분류를 모두 입력해주세요.')
              setIsSaving(false)
              return
            }

            // API 호출
            updateCareerMutation.mutate(careerData)
          }
          break

        case 'activity':
          if (activityRef.current) {
            const activityData = activityRef.current.getFormData()

            // 데이터 유효성 검사
            const hasEmptyCategory = activityData.some(
              item => !item.lawyerActivityCategoryName || item.lawyerActivityCategoryName.trim() === ''
            )
            if (hasEmptyCategory) {
              message.warning('활동 분류를 모두 입력해주세요.')
              setIsSaving(false)
              return
            }

            // API 호출
            updateActivityMutation.mutate(activityData)
          }
          break
      }
    } catch (error) {
      message.error('저장 중 오류가 발생했습니다.')
      console.error(error)
      setIsSaving(false)
    }
  }

  return (
    <>
      <header className={styles['lawyer-edit__header']}>
        <h1 className={styles['lawyer-edit__header-title']}>{state?.lawyerName} 변호사의 활동사항 화면입니다.</h1>
        <div className={styles['lawyer-edit__header-actions']}>
          <Button onClick={handleCancel}>취소</Button>
          <Button
            type='primary'
            onClick={handleSave}
            loading={
              isSaving ||
              updateBasicInfoMutation.isPending ||
              updateCareerMutation.isPending ||
              updateActivityMutation.isPending
            }
            disabled={
              updateBasicInfoMutation.isPending || updateCareerMutation.isPending || updateActivityMutation.isPending
            }
          >
            변경완료
          </Button>
        </div>
      </header>
      <main className='sub-main-container' style={{ padding: '16px' }}>
        <Tabs items={items} activeKey={activeTab} onChange={setActiveTab} />
      </main>
    </>
  )
}

